var AVATAR_DATA = {
  "astronaut": "data:image/webp;base64,",
  "robot": "data:image/webp;base64,",
  "ninja": "data:image/webp;base64,",
  "alien": "data:image/webp;base64,",
  "wizard": "data:image/webp;base64,",
  "fox": "data:image/webp;base64,",
  "panda": "data:image/webp;base64,",
  "dragon": "data:image/webp;base64,",
  "cat": "data:image/webp;base64,",
  "owl": "data:image/webp;base64,",
  "unicorn": "data:image/webp;base64,",
  "ghost": "data:image/webp;base64,"
};

// ---- Session state reducer (all 10 question types, unit-tested separately) ----

var AVATAR_IDS = ['astronaut','robot','ninja','alien','wizard','fox','panda','dragon','cat','owl','unicorn','ghost'];
var GRADED_TYPES = ['mc','tf','multi','image','ranking','matching','dragdrop'];
var UNGRADED_TYPES = ['rating','text','wordcloud'];

function defaultState(code) {
  return {
    code: code || 'LEARN6',
    phase: 'lobby',
    participants: {},
    question: null,
    answers: {},
    reveal: false,
    showBoard: false,
    finale: false
  };
}

// ---- Correctness checking, one function per question type family ----

function arraysEqualAsSets(a, b) {
  if (!Array.isArray(a) || !Array.isArray(b)) return false;
  if (a.length !== b.length) return false;
  var sa = a.slice().sort(function(x,y){return x-y;});
  var sb = b.slice().sort(function(x,y){return x-y;});
  for (var i = 0; i < sa.length; i++) if (sa[i] !== sb[i]) return false;
  return true;
}

function arraysEqualOrdered(a, b) {
  if (!Array.isArray(a) || !Array.isArray(b)) return false;
  if (a.length !== b.length) return false;
  for (var i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
  return true;
}

function pairSetsEqual(a, b) {
  if (!Array.isArray(a) || !Array.isArray(b)) return false;
  if (a.length !== b.length) return false;
  var norm = function(arr){ return arr.map(function(p){ return p[0]+':'+p[1]; }).sort(); };
  var na = norm(a), nb = norm(b);
  for (var i = 0; i < na.length; i++) if (na[i] !== nb[i]) return false;
  return true;
}

function placementSetsEqual(a, b) {
  if (!Array.isArray(a) || !Array.isArray(b)) return false;
  if (a.length !== b.length) return false;
  var norm = function(arr){ return arr.map(function(p){ return p.item+':'+p.zone; }).sort(); };
  var na = norm(a), nb = norm(b);
  for (var i = 0; i < na.length; i++) if (na[i] !== nb[i]) return false;
  return true;
}

function isCorrect(question, answer) {
  switch (question.type) {
    case 'mc': case 'tf': case 'image':
      return answer.option === question.correct;
    case 'multi':
      return arraysEqualAsSets(answer.options, question.correct);
    case 'ranking':
      return arraysEqualOrdered(answer.order, question.correctOrder);
    case 'matching':
      return pairSetsEqual(answer.pairs, question.correctPairs);
    case 'dragdrop':
      return placementSetsEqual(answer.placement, question.correctPlacement);
    case 'rating': case 'text': case 'wordcloud':
      return true; // ungraded, always "correct" for participation, 0 points awarded separately
    default:
      return false;
  }
}

function isGraded(type) {
  return GRADED_TYPES.indexOf(type) !== -1;
}

function validateAnswerShape(question, msg) {
  switch (question.type) {
    case 'mc': case 'tf': case 'image':
      return Number.isInteger(msg.option) && msg.option >= 0 && msg.option < (question.options||[]).length;
    case 'multi':
      return Array.isArray(msg.options) && msg.options.every(function(o){
        return Number.isInteger(o) && o >= 0 && o < (question.options||[]).length;
      });
    case 'rating':
      return Number.isInteger(msg.value) && msg.value >= question.scale.min && msg.value <= question.scale.max;
    case 'text': case 'wordcloud':
      return typeof msg.text === 'string' && msg.text.trim().length > 0 && msg.text.length <= 200;
    case 'ranking':
      return Array.isArray(msg.order) && msg.order.length === (question.items||[]).length;
    case 'matching':
      return Array.isArray(msg.pairs);
    case 'dragdrop':
      return Array.isArray(msg.placement);
    default:
      return false;
  }
}

function extractAnswerPayload(question, msg) {
  switch (question.type) {
    case 'mc': case 'tf': case 'image': return { option: msg.option };
    case 'multi': return { options: msg.options };
    case 'rating': return { value: msg.value };
    case 'text': case 'wordcloud': return { text: String(msg.text).slice(0,200) };
    case 'ranking': return { order: msg.order };
    case 'matching': return { pairs: msg.pairs };
    case 'dragdrop': return { placement: msg.placement };
    default: return {};
  }
}

function reduce(state, msg, now) {
  state = state || defaultState();
  switch (msg.type) {

    case 'join': {
      if (!msg.id || !msg.name) return state;
      var existing = state.participants[msg.id];
      var avatar = AVATAR_IDS.indexOf(msg.avatar) !== -1 ? msg.avatar : (existing ? existing.avatar : 'robot');
      state.participants[msg.id] = {
        id: msg.id,
        name: String(msg.name).slice(0, 40),
        avatar: avatar,
        score: existing ? existing.score : 0,
        lastDelta: existing ? existing.lastDelta : 0
      };
      return state;
    }

    case 'launch': {
      var q = msg.question;
      if (!q || !q.type || !q.text) return state;
      state.question = q;
      state.question.started = now;
      state.answers = {};
      state.reveal = false;
      state.showBoard = false;
      state.finale = false;
      state.phase = 'live';
      return state;
    }

    case 'answer': {
      if (!msg.id || !state.question) return { state: state, rejected: 'no_active_question' };
      if (state.answers[msg.id]) return { state: state, rejected: 'already_answered' };
      var deadline = state.question.started + state.question.duration * 1000;
      if (now > deadline) return { state: state, rejected: 'time_expired' };
      if (!validateAnswerShape(state.question, msg)) {
        return { state: state, rejected: 'invalid_option' };
      }
      var payload = extractAnswerPayload(state.question, msg);
      payload.time = now;
      state.answers[msg.id] = payload;
      return { state: state, rejected: null };
    }

    case 'reveal': {
      if (!state.question) return state;
      state.reveal = true;
      var q = state.question;
      var graded = isGraded(q.type);

      if (graded) {
        var all = Object.entries(state.answers || {});
        var correct = all
          .filter(function (e) { return isCorrect(q, e[1]); })
          .sort(function (a, b) { return a[1].time - b[1].time; });

        correct.forEach(function (entry, idx) {
          var id = entry[0], a = entry[1];
          var elapsed = Math.max(0, (a.time - q.started) / 1000);
          var remain = Math.max(0, 1 - elapsed / q.duration);
          var bonus = idx === 0 ? 100 : Math.round(10 + 90 * remain);
          var delta = 250 + bonus;
          if (!state.participants[id]) return;
          state.participants[id].score = (state.participants[id].score || 0) + delta;
          state.participants[id].lastDelta = delta;
          a.base = 250;
          a.bonus = bonus;
          a.correct = true;
          a.rank = 0;
        });
        // mark incorrect answers too, for UI clarity
        all.forEach(function(entry){
          var a = entry[1];
          if (a.correct === undefined) { a.correct = isCorrect(q, a); a.base = 0; a.bonus = 0; }
        });

        var sorted = Object.values(state.participants).sort(function (a, b) { return (b.score || 0) - (a.score || 0); });
        sorted.forEach(function (p, i) {
          var a = state.answers[p.id];
          if (a) a.rank = i + 1;
        });
      }
      return state;
    }

    case 'showBoard': {
      state.showBoard = true;
      return state;
    }

    case 'finale': {
      state.finale = true;
      return state;
    }

    case 'reset': {
      return defaultState(state.code);
    }

    default:
      return state;
  }
}

// ---- Persistent question bank validation/sanitization logic ----

// ============================================================
// Persistent Question Bank - pure logic (no Durable Object /
// storage APIs referenced here at all, so this can be fully
// unit-tested in plain Node before ever touching Cloudflare).
//
// Design: the admin UI edits the ENTIRE bank client-side, then
// sends the whole array back in one "save" request. This keeps
// the server-side surface area small (just validate + store one
// JSON blob) rather than building a full per-question CRUD API,
// which would be a lot more surface area to get right for a
// single-admin editing workflow.
// ============================================================

var QUESTION_TYPES = ['mc','tf','multi','rating','text','image','wordcloud','ranking','matching','dragdrop'];
var MAX_QUESTIONS = 20;
var MAX_TEXT_LEN = 300;
var MAX_OPTION_LEN = 200;
var MAX_OPTIONS = 6;

function isNonEmptyString(v, maxLen) {
  return typeof v === 'string' && v.trim().length > 0 && v.length <= (maxLen || MAX_TEXT_LEN);
}

// Returns null if valid, or a short string describing the first problem
// found (used both for rejecting bad saves and for admin-side inline
// error messages).
function validateQuestion(q, index) {
  var where = 'Question ' + (index + 1) + ': ';
  if (!q || typeof q !== 'object') return where + 'missing question object';
  if (QUESTION_TYPES.indexOf(q.type) === -1) return where + 'unknown question type "' + q.type + '"';
  if (!isNonEmptyString(q.text)) return where + 'question text is required';
  if (!Number.isInteger(q.duration) || q.duration < 5 || q.duration > 120) return where + 'duration must be between 5 and 120 seconds';

  switch (q.type) {
    case 'mc': case 'image': {
      if (!Array.isArray(q.options) || q.options.length < 2 || q.options.length > MAX_OPTIONS) return where + 'needs 2 to 6 answer options';
      if (!q.options.every(function(o){ return isNonEmptyString(o, MAX_OPTION_LEN); })) return where + 'all answer options must have text';
      if (!Number.isInteger(q.correct) || q.correct < 0 || q.correct >= q.options.length) return where + 'correct answer index is invalid';
      if (q.type === 'image' && q.media && q.media.kind === 'image' && !isNonEmptyString(q.media.url, 2000)) return where + 'image media needs a URL, or set media to null';
      break;
    }
    case 'tf': {
      if (!Array.isArray(q.options) || q.options.length !== 2) return where + 'true/false needs exactly 2 options';
      if (!Number.isInteger(q.correct) || (q.correct !== 0 && q.correct !== 1)) return where + 'correct answer must be option 0 or 1';
      break;
    }
    case 'multi': {
      if (!Array.isArray(q.options) || q.options.length < 2 || q.options.length > MAX_OPTIONS) return where + 'needs 2 to 6 answer options';
      if (!q.options.every(function(o){ return isNonEmptyString(o, MAX_OPTION_LEN); })) return where + 'all answer options must have text';
      if (!Array.isArray(q.correct) || q.correct.length === 0) return where + 'select at least one correct option';
      if (!q.correct.every(function(i){ return Number.isInteger(i) && i >= 0 && i < q.options.length; })) return where + 'correct answer indices are invalid';
      break;
    }
    case 'rating': {
      if (!q.scale || !Number.isInteger(q.scale.min) || !Number.isInteger(q.scale.max) || q.scale.min >= q.scale.max) return where + 'rating scale needs valid min/max';
      break;
    }
    case 'text': case 'wordcloud': {
      break; // no extra fields required beyond base text/duration
    }
    case 'ranking': {
      if (!Array.isArray(q.items) || q.items.length < 2 || q.items.length > MAX_OPTIONS) return where + 'needs 2 to 6 items to rank';
      if (!q.items.every(function(o){ return isNonEmptyString(o, MAX_OPTION_LEN); })) return where + 'all ranking items must have text';
      if (!Array.isArray(q.correctOrder) || q.correctOrder.length !== q.items.length) return where + 'correct order must list every item exactly once';
      break;
    }
    case 'matching': {
      if (!Array.isArray(q.items) || q.items.length < 2 || q.items.length > MAX_OPTIONS) return where + 'needs 2 to 6 left-side items';
      if (!Array.isArray(q.matchRight) || q.matchRight.length !== q.items.length) return where + 'right-side items must match left-side count';
      if (!Array.isArray(q.correctPairs) || q.correctPairs.length !== q.items.length) return where + 'every left item needs a correct pair';
      break;
    }
    case 'dragdrop': {
      if (!Array.isArray(q.items) || q.items.length < 2 || q.items.length > MAX_OPTIONS) return where + 'needs 2 to 6 draggable items';
      if (!Array.isArray(q.dropZones) || q.dropZones.length < 1) return where + 'needs at least 1 drop zone';
      if (!Array.isArray(q.correctPlacement) || q.correctPlacement.length !== q.items.length) return where + 'every item needs a correct zone';
      break;
    }
  }
  return null;
}

function validateBank(questions) {
  if (!Array.isArray(questions)) return 'Bank must be an array of questions';
  if (questions.length === 0) return 'Bank must contain at least 1 question';
  if (questions.length > MAX_QUESTIONS) return 'Bank cannot exceed ' + MAX_QUESTIONS + ' questions';
  for (var i = 0; i < questions.length; i++) {
    var err = validateQuestion(questions[i], i);
    if (err) return err;
  }
  return null;
}

// Strips any unexpected/extra fields and enforces length caps, so a
// malformed or oversized payload can never bloat storage or break
// rendering, even if validateBank somehow let something odd through.
function sanitizeQuestion(q) {
  var out = {
    id: isNonEmptyString(q.id, 60) ? q.id : ('q_' + Math.random().toString(36).slice(2)),
    type: q.type,
    text: String(q.text).slice(0, MAX_TEXT_LEN),
    duration: Math.max(5, Math.min(120, Number(q.duration) || 20)),
    media: (q.media && q.media.kind === 'image' && isNonEmptyString(q.media.url, 2000))
      ? { kind: 'image', url: String(q.media.url).slice(0, 2000) }
      : null
  };
  if (Array.isArray(q.options)) out.options = q.options.slice(0, MAX_OPTIONS).map(function(o){ return String(o).slice(0, MAX_OPTION_LEN); });
  if (q.correct !== undefined) out.correct = q.correct;
  if (q.scale) out.scale = { min: Number(q.scale.min), max: Number(q.scale.max), minLabel: q.scale.minLabel ? String(q.scale.minLabel).slice(0,40) : '', maxLabel: q.scale.maxLabel ? String(q.scale.maxLabel).slice(0,40) : '' };
  if (Array.isArray(q.items)) out.items = q.items.slice(0, MAX_OPTIONS).map(function(o){ return String(o).slice(0, MAX_OPTION_LEN); });
  if (Array.isArray(q.matchRight)) out.matchRight = q.matchRight.slice(0, MAX_OPTIONS).map(function(o){ return String(o).slice(0, MAX_OPTION_LEN); });
  if (Array.isArray(q.correctPairs)) out.correctPairs = q.correctPairs;
  if (Array.isArray(q.correctOrder)) out.correctOrder = q.correctOrder;
  if (Array.isArray(q.dropZones)) out.dropZones = q.dropZones.slice(0, MAX_OPTIONS).map(function(o){ return String(o).slice(0, MAX_OPTION_LEN); });
  if (Array.isArray(q.correctPlacement)) out.correctPlacement = q.correctPlacement;
  return out;
}

function sanitizeBank(questions) {
  return questions.slice(0, MAX_QUESTIONS).map(sanitizeQuestion);
}

// ---- Pure request-handling logic, decoupled from Durable Object storage ----
// so it can be unit tested directly. The real Durable Object class just
// wires these to this.ctx.storage.get/put.

function handleBankGet(storedBank) {
  var bank = storedBank || defaultBank();
  return { status: 200, body: { questions: bank } };
}

function handleBankPost(body) {
  if (!body || !Array.isArray(body.questions)) {
    return { status: 400, body: { error: 'Request must include a questions array' } };
  }
  var err = validateBank(body.questions);
  if (err) {
    return { status: 400, body: { error: err } };
  }
  var clean = sanitizeBank(body.questions);
  return { status: 200, body: { questions: clean }, toStore: clean };
}

