// ---- Durable Objects: one per live session, one singleton for the bank ----

export class SessionRoom {
  constructor(ctx, env) {
    this.ctx = ctx;
    this.env = env;
    this.sockets = new Set();
    this.session = null;
  }

  async ensureLoaded(defaultCode) {
    if (this.session) return;
    let saved = null;
    try { saved = await this.ctx.storage.get('session'); } catch (e) { saved = null; }
    this.session = saved || defaultState(defaultCode);
  }

  async persistAndBroadcast() {
    try { await this.ctx.storage.put('session', this.session); } catch (e) {}
    const payload = JSON.stringify({ kind: 'state', state: this.session });
    for (const sock of this.sockets) {
      try { sock.send(payload); } catch (e) { this.sockets.delete(sock); }
    }
  }

  async fetch(request) {
    const url = new URL(request.url);
    const codeParam = (url.searchParams.get('code') || 'LEARN6').toUpperCase();
    await this.ensureLoaded(codeParam);
    if (!this.session.code) this.session.code = codeParam;

    if (request.headers.get('Upgrade') !== 'websocket') {
      return new Response('Expected a WebSocket upgrade request', { status: 426 });
    }

    const pair = new WebSocketPair();
    const client = pair[0];
    const server = pair[1];
    server.accept();
    this.sockets.add(server);

    try { server.send(JSON.stringify({ kind: 'state', state: this.session })); } catch (e) {}

    server.addEventListener('message', (evt) => {
      let msg;
      try { msg = JSON.parse(evt.data); } catch (e) { return; }
      const now = Date.now();

      if (msg.type === 'answer') {
        const result = reduce(this.session, msg, now);
        this.session = result.state;
        if (result.rejected) {
          try { server.send(JSON.stringify({ kind: 'error', reason: result.rejected })); } catch (e) {}
        } else {
          this.persistAndBroadcast();
        }
      } else {
        this.session = reduce(this.session, msg, now);
        this.persistAndBroadcast();
      }
    });

    server.addEventListener('close', () => { this.sockets.delete(server); });
    server.addEventListener('error', () => { this.sockets.delete(server); });

    return new Response(null, { status: 101, webSocket: client });
  }
}

// ============================================================
// QuestionBank Durable Object - a SINGLETON (always accessed via
// the same fixed name, e.g. env.QUESTION_BANK.idFromName('global'))
// so every admin session reads/writes the SAME persistent bank,
// independent of any individual quiz session's SessionRoom.
//
// This is intentionally simple: two plain HTTP endpoints, no
// WebSocket, no per-question CRUD surface - the admin UI edits the
// whole bank client-side and saves it in one request. All actual
// validation/sanitization logic lives in bank.js (already unit
// tested in isolation) - this class only wires that logic to
// this.ctx.storage.
// ============================================================
export class QuestionBank {
  constructor(ctx, env) {
    this.ctx = ctx;
    this.env = env;
  }

  async fetch(request) {
    const url = new URL(request.url);
    const corsHeaders = {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type'
    };

    if (request.method === 'OPTIONS') {
      return new Response(null, { status: 204, headers: corsHeaders });
    }

    if (request.method === 'GET') {
      let stored = null;
      try { stored = await this.ctx.storage.get('bank'); } catch (e) { stored = null; }
      const result = handleBankGet(stored);
      return Response.json(result.body, { status: result.status, headers: corsHeaders });
    }

    if (request.method === 'POST') {
      let body;
      try { body = await request.json(); } catch (e) {
        return Response.json({ error: 'Invalid JSON body' }, { status: 400, headers: corsHeaders });
      }
      const result = handleBankPost(body);
      if (result.status === 200 && result.toStore) {
        try { await this.ctx.storage.put('bank', result.toStore); } catch (e) {
          return Response.json({ error: 'Failed to save bank' }, { status: 500, headers: corsHeaders });
        }
      }
      return Response.json(result.body, { status: result.status, headers: corsHeaders });
    }

    return new Response('Method not allowed', { status: 405, headers: corsHeaders });
  }
}

