function adminHtml() {
  var avatarScript = '<script>var AVATAR_DATA = ' + JSON.stringify(AVATAR_DATA) + ';</' + 'script>';
  return "<!doctype html>\n<html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Live Quiz Admin</title>\n<style>\n:root{--blue:#0000FF;--sky:#00A2FF;--neon:#CFF91C;--yellow:#FEDA00;--green:#09BC09;--navy:#0E1540;--ink:#1A1E36;--grey:#929292;--bg:#F6F7FB}\n*{box-sizing:border-box}\nbody{margin:0;font-family:Arial,Helvetica,sans-serif;color:var(--ink);background:var(--bg);position:relative;min-height:100vh}\n.bgwrap{position:fixed;inset:0;z-index:0;background-image:url('data:image/webp;base64,');background-size:cover;background-position:center top;background-repeat:no-repeat}\n.top{height:6px;background:linear-gradient(90deg,var(--blue),var(--neon));position:relative;z-index:1}\nheader{padding:18px 24px;display:flex;justify-content:space-between;align-items:center;position:relative;z-index:1;flex-wrap:wrap;gap:8px}\n.brand{font-weight:900;color:var(--navy);font-size:14px;letter-spacing:.2px}\n.pill{border-radius:999px;padding:6px 14px;font-size:11px;font-weight:800;background:#ECFFEC;color:#067806}\n.wrap{max-width:820px;margin:0 auto;padding:20px 18px 60px;position:relative;z-index:1}\n.gcard{background:rgba(255,255,255,.82);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);border:1px solid rgba(255,255,255,.9);border-radius:26px;padding:26px;box-shadow:0 12px 34px rgba(14,21,64,.14);margin-bottom:18px}\nh1,h2{margin:0 0 6px;color:var(--navy)}\nh1{font-size:22px;font-weight:900}\nh2{font-size:19px;font-weight:900}\n.gtitle{font-size:26px;font-weight:900;background:linear-gradient(90deg,var(--blue),var(--neon));-webkit-background-clip:text;background-clip:text;color:transparent;margin:0}\n.center{text-align:center}\n.muted{color:var(--grey);font-size:12.5px}\n.hide{display:none!important}\nbutton,input,select,textarea{font:inherit}\nbutton{border:0;border-radius:16px;padding:13px 18px;font-weight:800;cursor:pointer;transition:transform .12s ease}\nbutton:active{transform:scale(.97)}\n.gbtn{background:var(--blue);color:#fff;width:100%;box-shadow:0 8px 18px rgba(0,0,255,.22)}\n.secbtn{background:#EEF1FF;color:var(--blue)}\n.dangerbtn{background:#FFEAEA;color:#B50000}\n.nextbtn{background:var(--green);color:#fff;box-shadow:0 8px 18px rgba(9,188,9,.25)}\ninput,textarea{width:100%;padding:13px 14px;border:1.5px solid #E1E5F2;border-radius:14px;margin:6px 0 14px;background:rgba(255,255,255,.9);resize:none;overflow:hidden;line-height:1.4}\ntextarea{min-height:44px;font-family:Arial,Helvetica,sans-serif}\nlabel{font-weight:800;font-size:11.5px;color:var(--navy);text-transform:uppercase;letter-spacing:.3px}\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:14px}\n.stat{background:rgba(255,255,255,.7);border-radius:16px;padding:12px 14px}\n.stat b{display:block;font-size:22px;color:var(--navy)}\n.code{font-size:34px;letter-spacing:6px;font-weight:900;background:linear-gradient(90deg,var(--blue),var(--neon));-webkit-background-clip:text;background-clip:text;color:transparent}\n.msg{display:none;border-radius:12px;padding:9px 12px;margin:6px 0 12px;font-size:12.5px;font-weight:700}\n.msg.show{display:block}\n.msg.err{background:#FFECEC;color:#B50000}\n.msg.info{background:#EAF3FF;color:#0000FF}\n.qcounter{font-size:11px;font-weight:800;color:var(--navy);background:#EEF1FF;border-radius:999px;padding:5px 12px;display:inline-block;margin-bottom:10px}\n\n.avgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:16px 0}\n.avitem{display:flex;flex-direction:column;align-items:center;gap:6px;cursor:pointer}\n.avorb{width:56px;height:56px;border-radius:50%;display:flex;align-items:center;justify-content:center;border:3px solid transparent;box-shadow:0 4px 10px rgba(14,21,64,.10);transition:transform .15s,border-color .15s}\n.avorb img{width:70%;height:70%;object-fit:contain}\n.avitem.selected .avorb{border-color:var(--blue);transform:scale(1.08);box-shadow:0 0 0 4px rgba(0,0,255,.15)}\n.avlabel{font-size:9.5px;font-weight:800;color:var(--navy);text-transform:uppercase;letter-spacing:.2px}\n.avmini{width:36px;height:36px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0}\n.avmini img{width:70%;height:70%;object-fit:contain}\n\n.ringwrap{display:flex;justify-content:center;margin:20px 0}\n.ring{position:relative;width:120px;height:120px}\n.ring svg{transform:rotate(-90deg)}\n.ring .num{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center}\n.ring .num b{font-size:30px;color:var(--navy);line-height:1}\n.ring .num span{font-size:9px;color:var(--grey);font-weight:800;letter-spacing:.5px}\n\n.answers{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:8px}\n.answer{position:relative;min-height:64px;border-radius:16px;padding:14px 16px 14px 46px;text-align:left;background:rgba(255,255,255,.92);color:var(--ink);font-weight:700;font-size:13.5px;line-height:1.25;border:2px solid #E7EAF3;box-shadow:0 4px 12px rgba(14,21,64,.08)}\n.answer[data-i=\"0\"]{border-left:5px solid var(--blue)}\n.answer[data-i=\"1\"]{border-left:5px solid var(--sky)}\n.answer[data-i=\"2\"]{border-left:5px solid var(--yellow)}\n.answer[data-i=\"3\"]{border-left:5px solid var(--green)}\n.answer[data-i=\"4\"]{border-left:5px solid #6A4CF5}\n.answer[data-i=\"5\"]{border-left:5px solid #E0527A}\n.answer .letter{position:absolute;left:12px;top:50%;transform:translateY(-50%);width:24px;height:24px;border-radius:50%;background:rgba(0,0,0,.06);display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:900;color:var(--navy)}\n.answer.selected{border-color:#1A1E36;box-shadow:0 0 0 3px rgba(26,30,54,.18)}\n.answer.selected::after{content:'Selected';position:absolute;top:6px;right:10px;font-size:9px;font-weight:900;background:var(--navy);color:#fff;padding:2px 7px;border-radius:999px}\n.answer[disabled]{opacity:.6;cursor:default}\n\n.basepts{font-size:22px;color:var(--blue);font-weight:900;margin-top:6px}\n.bonus{font-size:44px;font-weight:900;color:var(--green);animation:pop .5s ease-out}\n@keyframes pop{0%{transform:scale(.3);opacity:0}70%{transform:scale(1.15)}100%{transform:scale(1);opacity:1}}\n.rankline{font-size:16px;font-weight:800;color:var(--navy);margin-top:6px}\n\n.leader{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:10px}\n.lrow{display:grid;grid-template-columns:30px 36px 1fr auto;gap:10px;align-items:center;background:rgba(255,255,255,.85);border-radius:16px;padding:11px 14px;box-shadow:0 4px 10px rgba(14,21,64,.08)}\n.lrow.top1{background:#FFFDEC;box-shadow:0 6px 16px rgba(254,218,0,.25);border:1.5px solid #FEDA00}\n.lrank{width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:12.5px;background:#DDE2EE;color:var(--navy)}\n.lrank.r1{background:var(--yellow);color:#1A1E36}\n.lrank.r2{background:var(--sky);color:#fff}\n.lrank.r3{background:var(--green);color:#fff}\n.lname{font-weight:800;font-size:13.5px;color:var(--navy)}\n.lfastest{font-size:9.5px;font-weight:800;color:var(--green);display:flex;align-items:center;gap:3px;margin-top:1px}\n.lscore{font-weight:900;font-size:15px;color:var(--navy);text-align:right}\n.ldelta{font-size:11px;font-weight:900;color:var(--green);text-align:right}\n\n.dotpulse{display:flex;gap:7px;justify-content:center;margin-top:14px}\n.dotpulse span{width:9px;height:9px;border-radius:50%;background:var(--blue);animation:dotanim 1.2s infinite ease-in-out}\n.dotpulse span:nth-child(2){animation-delay:.2s;background:var(--sky)}\n.dotpulse span:nth-child(3){animation-delay:.4s;background:var(--green)}\n@keyframes dotanim{0%,80%,100%{transform:scale(.6);opacity:.4}40%{transform:scale(1);opacity:1}}\n\n.confetti-piece{position:fixed;top:-20px;pointer-events:none;z-index:5;border-radius:2px}\n@keyframes confettiFall{to{transform:translateY(110vh) rotate(360deg);opacity:0}}\n\n@media(max-width:480px){\n  .avgrid{grid-template-columns:repeat(4,1fr);gap:10px}\n  .avorb{width:48px;height:48px}\n  .answers{grid-template-columns:1fr}\n  .ring{width:100px;height:100px}\n  .ring .num b{font-size:24px}\n  .gtitle{font-size:22px}\n}\n\n.tabbar{display:flex;gap:8px;margin-bottom:16px}\n.tabbtn{flex:1;background:rgba(255,255,255,.6);color:var(--navy);border:1.5px solid #E1E5F2;padding:11px;border-radius:14px;font-weight:800;font-size:13px}\n.tabbtn.active{background:var(--blue);color:#fff;border-color:var(--blue)}\n.qlist{display:flex;flex-direction:column;gap:10px;margin:14px 0}\n.qlistitem{background:rgba(255,255,255,.85);border:1px solid #E7EAF3;border-radius:14px;padding:12px 14px;display:flex;align-items:center;gap:10px}\n.qtypebadge{font-size:9.5px;font-weight:900;text-transform:uppercase;letter-spacing:.3px;padding:4px 9px;border-radius:999px;color:#fff;flex-shrink:0}\n.qtb-mc{background:var(--blue)}.qtb-tf{background:var(--sky)}.qtb-multi{background:#6A4CF5}\n.qtb-rating{background:#FF8A3D}.qtb-text{background:#929292}.qtb-image{background:#00A2FF}\n.qtb-wordcloud{background:#00BFAE}.qtb-ranking{background:#E0527A}.qtb-matching{background:#09BC09}\n.qtb-dragdrop{background:#0E1540}\n.qlisttext{flex:1;font-size:13px;font-weight:700;color:var(--navy);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.qlistbtns{display:flex;gap:6px;flex-shrink:0}\n.qsmallbtn{padding:7px 10px;font-size:11px;border-radius:10px;font-weight:800}\n.qsmallbtn.edit{background:#EEF1FF;color:var(--blue)}\n.qsmallbtn.up,.qsmallbtn.down{background:#F3F4F8;color:var(--navy);padding:7px 9px}\n.qsmallbtn.del{background:#FFECEC;color:#B50000}\n.addqbtn{background:var(--green);color:#fff;width:100%;margin-top:6px}\n.savebankbtn{background:var(--blue);color:#fff;width:100%;margin-top:14px}\n.bankdirty{background:#FFF6DC;color:#8A6300;border-radius:12px;padding:9px 12px;font-size:12px;font-weight:700;margin-bottom:12px}\n.typeselect{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin:10px 0 16px}\n.typeopt{background:rgba(255,255,255,.7);border:1.5px solid #E1E5F2;border-radius:12px;padding:9px 6px;text-align:center;font-size:9.5px;font-weight:800;color:var(--navy);cursor:pointer}\n.typeopt.selected{background:var(--blue);color:#fff;border-color:var(--blue)}\n.fieldgroup{border:1px solid #E7EAF3;border-radius:14px;padding:12px;margin:10px 0;background:rgba(255,255,255,.5)}\n.fieldgrouphead{font-size:11px;font-weight:800;color:var(--navy);text-transform:uppercase;letter-spacing:.3px;margin-bottom:8px;display:flex;justify-content:space-between;align-items:center}\n.optrow{display:flex;gap:8px;align-items:center;margin-bottom:8px}\n.optrow input[type=text]{flex:1;margin:0}\n.optrow input[type=radio],.optrow input[type=checkbox]{width:18px;height:18px;flex-shrink:0}\n.miniaddbtn{background:#EEF1FF;color:var(--blue);padding:8px 12px;font-size:12px;border-radius:10px}\n.minidelbtn{background:#FFECEC;color:#B50000;padding:6px 9px;font-size:11px;border-radius:8px;flex-shrink:0}\n.zonepicker{width:100%;padding:10px;border:1.5px solid #E1E5F2;border-radius:10px;background:rgba(255,255,255,.9);margin-top:4px}\n.editorcancel{background:#F3F4F8;color:var(--navy)}\n.qpreviewcard{background:rgba(255,255,255,.85);border:1.5px solid #E1E5F2;border-radius:16px;padding:16px;margin:12px 0}\n.qpreviewlist{margin:8px 0 0;padding-left:18px;font-size:12.5px;color:var(--ink)}\n.qpreviewlist li{margin-bottom:4px}\n</style></head>\n<body>\n<div class=\"bgwrap\"></div>\n<div class=\"top\"></div>\n<header><div class=\"brand\">ONITY CENTER OF LEARNING EXCELLENCE &mdash; ADMIN</div><span class=\"pill\" id=\"connpill\">Connecting</span></header>\n<main class=\"wrap\">\n\n<div class=\"gcard\">\n  <div class=\"grid2\">\n    <div>\n      <div class=\"muted\" style=\"text-transform:uppercase;font-weight:800;letter-spacing:.3px\">Session Code</div>\n      <div class=\"code\" id=\"code\">------</div>\n    </div>\n    <div class=\"grid2\">\n      <div class=\"stat\"><span class=\"muted\">Participants</span><b id=\"pc\">0</b></div>\n      <div class=\"stat\"><span class=\"muted\">Answered</span><b id=\"ac\">0</b></div>\n    </div>\n  </div>\n</div>\n\n<div class=\"tabbar\">\n  <button class=\"tabbtn active\" id=\"tabBank\">Manage Question Bank</button>\n  <button class=\"tabbtn\" id=\"tabRun\">Run Session</button>\n</div>\n\n<!-- ==================== BANK MANAGER TAB ==================== -->\n<div id=\"bankTabView\">\n\n  <div id=\"qlistView\">\n    <div class=\"gcard\">\n      <h2 class=\"gtitle\" style=\"font-size:22px\">Question Bank</h2>\n      <div class=\"muted\" id=\"qcountLabel\" style=\"margin-bottom:8px\">0 of 20 questions</div>\n      <div class=\"msg err bankdirty hide\" id=\"bankDirty\">You have unsaved changes.</div>\n      <div class=\"msg\" id=\"bankMsg\"></div>\n      <div class=\"qlist\" id=\"qlist\"></div>\n      <button class=\"addqbtn\" id=\"addQuestionBtn\">+ Add Question</button>\n      <button class=\"savebankbtn\" id=\"saveBankBtn\">Save Bank</button>\n    </div>\n  </div>\n\n  <div id=\"qeditorView\" class=\"hide\">\n    <div class=\"gcard\">\n      <h2 class=\"gtitle\" style=\"font-size:22px\">Edit Question</h2>\n      <label>Question type</label>\n      <div class=\"typeselect\" id=\"typePicker\"></div>\n      <div id=\"typeFields\"></div>\n      <div class=\"msg err\" id=\"editorMsg\"></div>\n      <div style=\"display:flex;gap:10px;margin-top:14px\">\n        <button class=\"editorcancel\" id=\"editorCancel\" style=\"flex:1\">Cancel</button>\n        <button class=\"gbtn\" id=\"editorSave\" style=\"flex:1\">Save Question</button>\n      </div>\n    </div>\n  </div>\n\n</div>\n\n<!-- ==================== RUN SESSION TAB ==================== -->\n<div id=\"runTabView\" class=\"hide\">\n\n  <div id=\"runSetup\">\n    <div class=\"gcard\">\n      <div class=\"qcounter\" id=\"runQCounter\">Question 1 of 20</div>\n      <div id=\"runQPreview\"></div>\n      <div style=\"display:flex;gap:10px;flex-wrap:wrap;margin-top:14px\">\n        <button class=\"gbtn\" id=\"launchFromBank\" style=\"flex:1;min-width:160px\">Launch Question</button>\n        <button class=\"secbtn\" id=\"skipQuestion\">Skip</button>\n      </div>\n    </div>\n  </div>\n\n  <div id=\"runLive\" class=\"gcard hide\">\n    <div class=\"qcounter\" id=\"liveQCounter\">Question 1 of 20</div>\n    <div class=\"ringwrap\"><div class=\"ring\">\n      <svg width=\"120\" height=\"120\" viewBox=\"0 0 120 120\">\n        <circle cx=\"60\" cy=\"60\" r=\"52\" fill=\"none\" stroke=\"#E7ECF5\" stroke-width=\"9\"/>\n        <circle cx=\"60\" cy=\"60\" r=\"52\" fill=\"none\" stroke=\"url(#ringGradA)\" stroke-width=\"9\" stroke-linecap=\"round\" id=\"ringProgress\"/>\n        <defs><linearGradient id=\"ringGradA\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n          <stop offset=\"0%\" stop-color=\"#CFF91C\"/><stop offset=\"100%\" stop-color=\"#09BC09\"/>\n        </linearGradient></defs>\n      </svg>\n      <div class=\"num\"><b id=\"ringNum\">--</b><span>SECONDS</span></div>\n    </div></div>\n    <h1 id=\"liveQText\" style=\"text-align:center\"></h1>\n    <div id=\"dist\"></div>\n\n    <div id=\"preRevealRow\" style=\"display:flex;gap:10px;flex-wrap:wrap;margin-top:18px\">\n      <button class=\"gbtn\" id=\"revealBtn\" style=\"flex:1;min-width:160px\">Reveal Answer &amp; Score</button>\n    </div>\n    <div id=\"postRevealRow\" class=\"hide\" style=\"display:flex;gap:10px;flex-wrap:wrap;margin-top:12px\">\n      <button class=\"nextbtn\" id=\"nextQuestionBtn\" style=\"flex:1;min-width:160px\">Next Question</button>\n      <button class=\"gbtn hide\" id=\"finaleBtn\" style=\"flex:1;min-width:160px\">Show Final Results</button>\n    </div>\n    <div style=\"display:flex;gap:10px;flex-wrap:wrap;margin-top:12px\">\n      <button class=\"secbtn\" id=\"showLeaderboardBtn\" style=\"flex:1\">Show Leaderboard</button>\n      <button class=\"dangerbtn\" id=\"resetSessionBtn\" style=\"flex:1\">Reset Session</button>\n    </div>\n  </div>\n\n  <div class=\"gcard hide\" id=\"lb\">\n    <h2 class=\"gtitle\" style=\"font-size:22px\">Leaderboard</h2>\n    <ol class=\"leader\" id=\"leader\" style=\"list-style:none;padding:0\"></ol>\n  </div>\n\n</div>\n\n</main>\n" + avatarScript + '<script>' + "// ============================================================\n// Glue code: session-code generation, connection status pill,\n// tab switching between \"Manage Bank\" and \"Run Session\", and\n// bootstrapping the bank fetch + run-session initialization.\n// ============================================================\n\nfunction genSessionCode(){\n  var c = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789', s = '';\n  for (var i = 0; i < 6; i++) s += c[Math.floor(Math.random()*c.length)];\n  return s;\n}\nvar params = new URLSearchParams(location.search);\nvar sessionCode = (params.get('code') || '').toUpperCase();\nif (!sessionCode){\n  sessionCode = genSessionCode();\n  var u = new URL(location.href);\n  u.searchParams.set('code', sessionCode);\n  history.replaceState(null, '', u);\n}\ndocument.getElementById('code').textContent = sessionCode;\n\nfunction setConnPill(ok, label){\n  var p = document.getElementById('connpill');\n  p.textContent = label;\n  p.style.background = ok ? '#ECFFEC' : '#FFECEC';\n  p.style.color = ok ? '#067806' : '#B50000';\n}\n\nfunction avatarImg(id){\n  var src = (typeof AVATAR_DATA !== 'undefined' && AVATAR_DATA[id]) ? AVATAR_DATA[id] : '';\n  return '<img src=\"' + src + '\" alt=\"' + id + '\">';\n}\n\ndocument.getElementById('tabBank').onclick = function(){\n  document.getElementById('tabBank').classList.add('active');\n  document.getElementById('tabRun').classList.remove('active');\n  document.getElementById('bankTabView').classList.remove('hide');\n  document.getElementById('runTabView').classList.add('hide');\n};\n\ndocument.getElementById('tabRun').onclick = function(){\n  document.getElementById('tabRun').classList.add('active');\n  document.getElementById('tabBank').classList.remove('active');\n  document.getElementById('runTabView').classList.remove('hide');\n  document.getElementById('bankTabView').classList.add('hide');\n  // Only initialize the session socket once, the first time this tab is opened.\n  if (!runState.ws){\n    initRunSession(sessionCode, bankState.questions.length ? bankState.questions : []);\n  }\n};\n\n// Bootstrap: fetch the persistent bank first (needed by both tabs), then\n// the Run Session tab can immediately use whatever was loaded whenever\n// the admin switches to it.\nfetchBank();\n\n\n// ============================================================\n// Admin Question Bank Manager\n// Handles: fetching/saving the persistent bank, list view with\n// reorder/delete, add/edit forms per question type, and exposes\n// bankState + helpers used by the Run Session view.\n// ============================================================\nvar TYPE_LABELS = {\n  mc: 'Multiple Choice', tf: 'True / False', multi: 'Multiple Response',\n  rating: 'Rating Scale', text: 'Open Text', image: 'Image-Based',\n  wordcloud: 'Word Cloud', ranking: 'Ranking', matching: 'Matching', dragdrop: 'Drag & Drop'\n};\nvar TYPE_ORDER = ['mc','tf','multi','rating','text','image','wordcloud','ranking','matching','dragdrop'];\n\nvar bankState = { questions: [], dirty: false, editingIndex: null, editingDraft: null };\n\nfunction newBlankQuestion(type) {\n  var base = { id: 'q_' + Math.random().toString(36).slice(2), type: type, text: '', duration: 20, media: null };\n  switch (type) {\n    case 'mc': case 'image': return Object.assign(base, { options:['','','',''], correct:0 });\n    case 'tf': return Object.assign(base, { options:['True','False'], correct:0 });\n    case 'multi': return Object.assign(base, { options:['','','',''], correct:[] });\n    case 'rating': return Object.assign(base, { scale:{min:1,max:5,minLabel:'',maxLabel:''} });\n    case 'text': case 'wordcloud': return base;\n    case 'ranking': return Object.assign(base, { items:['',''] });\n    case 'matching': return Object.assign(base, { items:['',''], matchRight:['',''] });\n    case 'dragdrop': return Object.assign(base, { items:['',''], dropZones:['','']});\n    default: return base;\n  }\n}\n\nasync function fetchBank(){\n  try {\n    var res = await fetch('/api/bank');\n    var data = await res.json();\n    bankState.questions = data.questions || [];\n    bankState.dirty = false;\n  } catch(e) {\n    bankState.questions = [];\n  }\n  renderBankList();\n}\n\nasync function saveBank(){\n  var body = { questions: bankState.questions };\n  try {\n    var res = await fetch('/api/bank', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(body) });\n    var data = await res.json();\n    if (res.status === 200){\n      bankState.questions = data.questions;\n      bankState.dirty = false;\n      showMsg('bankMsg', 'Bank saved successfully.', true);\n    } else {\n      showMsg('bankMsg', data.error || 'Could not save the bank.', false);\n    }\n  } catch(e){\n    showMsg('bankMsg', 'Network error while saving.', false);\n  }\n  renderBankList();\n}\n\nfunction showMsg(id, text, ok){\n  var el = document.getElementById(id);\n  if (!el) return;\n  el.textContent = text;\n  el.className = 'msg show ' + (ok ? 'info' : 'err');\n  setTimeout(function(){ el.classList.remove('show'); }, 3500);\n}\n\nfunction renderBankList(){\n  var listEl = document.getElementById('qlist');\n  if (!listEl) return;\n  var dirtyBanner = document.getElementById('bankDirty');\n  if (dirtyBanner) dirtyBanner.classList.toggle('hide', !bankState.dirty);\n\n  listEl.innerHTML = bankState.questions.map(function(q, i){\n    var preview = q.text ? (q.text.length > 60 ? q.text.slice(0,60)+'\\u2026' : q.text) : '(empty question)';\n    return '<div class=\"qlistitem\">' +\n      '<span class=\"qtypebadge qtb-' + q.type + '\">' + (TYPE_LABELS[q.type]||q.type) + '</span>' +\n      '<span class=\"qlisttext\">' + preview + '</span>' +\n      '<span class=\"qlistbtns\">' +\n        '<button class=\"qsmallbtn up\" data-act=\"up\" data-i=\"'+i+'\" '+(i===0?'disabled':'')+'>\\u2191</button>' +\n        '<button class=\"qsmallbtn down\" data-act=\"down\" data-i=\"'+i+'\" '+(i===bankState.questions.length-1?'disabled':'')+'>\\u2193</button>' +\n        '<button class=\"qsmallbtn edit\" data-act=\"edit\" data-i=\"'+i+'\">Edit</button>' +\n        '<button class=\"qsmallbtn del\" data-act=\"del\" data-i=\"'+i+'\">Delete</button>' +\n      '</span></div>';\n  }).join('');\n\n  Array.prototype.forEach.call(listEl.querySelectorAll('button'), function(btn){\n    btn.onclick = function(){\n      var i = +btn.getAttribute('data-i');\n      var act = btn.getAttribute('data-act');\n      if (act === 'up' && i > 0){\n        var tmp = bankState.questions[i-1]; bankState.questions[i-1] = bankState.questions[i]; bankState.questions[i] = tmp;\n        bankState.dirty = true; renderBankList();\n      } else if (act === 'down' && i < bankState.questions.length-1){\n        var tmp2 = bankState.questions[i+1]; bankState.questions[i+1] = bankState.questions[i]; bankState.questions[i] = tmp2;\n        bankState.dirty = true; renderBankList();\n      } else if (act === 'edit'){\n        openEditor(i);\n      } else if (act === 'del'){\n        if (bankState.questions.length <= 1){ showMsg('bankMsg','The bank must have at least 1 question.', false); return; }\n        bankState.questions.splice(i,1);\n        bankState.dirty = true; renderBankList();\n      }\n    };\n  });\n\n  var countEl = document.getElementById('qcountLabel');\n  if (countEl) countEl.textContent = bankState.questions.length + ' of 20 questions';\n}\n\nfunction openEditor(index){\n  bankState.editingIndex = index;\n  bankState.editingDraft = index === null ? null : JSON.parse(JSON.stringify(bankState.questions[index]));\n  document.getElementById('qlistView').classList.add('hide');\n  document.getElementById('qeditorView').classList.remove('hide');\n  renderEditorTypePicker();\n  renderEditorFields();\n}\n\nfunction closeEditor(){\n  bankState.editingIndex = null;\n  bankState.editingDraft = null;\n  document.getElementById('qlistView').classList.remove('hide');\n  document.getElementById('qeditorView').classList.add('hide');\n}\n\ndocument.getElementById('addQuestionBtn').onclick = function(){\n  var q = newBlankQuestion('mc');\n  bankState.questions.push(q);\n  bankState.dirty = true;\n  openEditor(bankState.questions.length - 1);\n};\n\ndocument.getElementById('editorCancel').onclick = function(){ closeEditor(); };\ndocument.getElementById('editorSave').onclick = function(){\n  var draft = bankState.editingDraft;\n  var err = validateDraftClientSide(draft);\n  if (err){ showMsg('editorMsg', err, false); return; }\n  bankState.questions[bankState.editingIndex] = draft;\n  bankState.dirty = true;\n  closeEditor();\n  renderBankList();\n};\n\ndocument.getElementById('saveBankBtn').onclick = function(){ saveBank(); };\n\nfunction renderEditorTypePicker(){\n  var wrap = document.getElementById('typePicker');\n  wrap.innerHTML = TYPE_ORDER.map(function(t){\n    var sel = bankState.editingDraft.type === t ? ' selected' : '';\n    return '<div class=\"typeopt'+sel+'\" data-type=\"'+t+'\">'+TYPE_LABELS[t]+'</div>';\n  }).join('');\n  Array.prototype.forEach.call(wrap.querySelectorAll('.typeopt'), function(el){\n    el.onclick = function(){\n      var t = el.getAttribute('data-type');\n      if (t === bankState.editingDraft.type) return;\n      var keepText = bankState.editingDraft.text;\n      var keepDuration = bankState.editingDraft.duration;\n      bankState.editingDraft = newBlankQuestion(t);\n      bankState.editingDraft.text = keepText;\n      bankState.editingDraft.duration = keepDuration;\n      renderEditorTypePicker();\n      renderEditorFields();\n    };\n  });\n}\n\nfunction autoResizeTA(el){ el.style.height='auto'; el.style.height=(el.scrollHeight)+'px'; }\n\n\n// ============================================================\n// Type-specific editor field renderers. Each renders into #typeFields\n// and wires inputs directly onto bankState.editingDraft so there is\n// one single source of truth (no separate \"form state\" to sync back).\n// ============================================================\n\nfunction renderEditorFields(){\n  var draft = bankState.editingDraft;\n  var host = document.getElementById('typeFields');\n\n  var baseHtml =\n    '<label>Question text</label>' +\n    '<textarea id=\"fText\" rows=\"1\">' + escapeHtml(draft.text) + '</textarea>' +\n    '<label>Duration (seconds)</label>' +\n    '<select id=\"fDuration\">' +\n      [10,15,20,25,30,45,60].map(function(s){ return '<option'+(draft.duration===s?' selected':'')+'>'+s+'</option>'; }).join('') +\n    '</select>';\n\n  host.innerHTML = baseHtml + '<div id=\"typeSpecificFields\"></div>';\n\n  var qText = document.getElementById('fText');\n  autoResizeTA(qText);\n  qText.oninput = function(){ draft.text = qText.value; autoResizeTA(qText); };\n  document.getElementById('fDuration').onchange = function(e){ draft.duration = +e.target.value; };\n\n  var specHost = document.getElementById('typeSpecificFields');\n  switch (draft.type) {\n    case 'mc': case 'image': renderOptionsSingleCorrect(specHost, draft, draft.type==='image'); break;\n    case 'tf': renderTrueFalse(specHost, draft); break;\n    case 'multi': renderOptionsMultiCorrect(specHost, draft); break;\n    case 'rating': renderRatingFields(specHost, draft); break;\n    case 'text': case 'wordcloud': /* no extra fields */ break;\n    case 'ranking': renderRankingFields(specHost, draft); break;\n    case 'matching': renderMatchingFields(specHost, draft); break;\n    case 'dragdrop': renderDragDropFields(specHost, draft); break;\n  }\n}\n\nfunction escapeHtml(s){\n  return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;');\n}\n\n// ---- Multiple choice / Image-based (single correct answer) ----\nfunction renderOptionsSingleCorrect(host, draft, isImage){\n  function paint(){\n    var rows = draft.options.map(function(o,i){\n      return '<div class=\"optrow\">' +\n        '<input type=\"radio\" name=\"correctRadio\" '+(draft.correct===i?'checked':'')+' data-i=\"'+i+'\">' +\n        '<input type=\"text\" value=\"'+escapeHtml(o)+'\" data-i=\"'+i+'\" placeholder=\"Option '+(i+1)+'\">' +\n        (draft.options.length>2 ? '<button class=\"minidelbtn\" data-i=\"'+i+'\">Remove</button>' : '') +\n      '</div>';\n    }).join('');\n    var mediaField = isImage ?\n      '<label style=\"margin-top:10px;display:block\">Image URL (optional)</label>' +\n      '<input type=\"text\" id=\"fMediaUrl\" value=\"'+escapeHtml(draft.media && draft.media.url || '')+'\" placeholder=\"https://...\">' : '';\n    host.innerHTML =\n      '<div class=\"fieldgroup\"><div class=\"fieldgrouphead\"><span>Answer options - select the correct one</span></div>' +\n      rows +\n      (draft.options.length < 6 ? '<button class=\"miniaddbtn\" id=\"addOpt\">+ Add option</button>' : '') +\n      mediaField +\n      '</div>';\n\n    Array.prototype.forEach.call(host.querySelectorAll('input[type=radio]'), function(r){\n      r.onchange = function(){ draft.correct = +r.getAttribute('data-i'); };\n    });\n    Array.prototype.forEach.call(host.querySelectorAll('input[type=text][data-i]'), function(inp){\n      inp.oninput = function(){ draft.options[+inp.getAttribute('data-i')] = inp.value; };\n    });\n    Array.prototype.forEach.call(host.querySelectorAll('.minidelbtn'), function(btn){\n      btn.onclick = function(){\n        var i = +btn.getAttribute('data-i');\n        draft.options.splice(i,1);\n        if (draft.correct >= draft.options.length) draft.correct = 0;\n        if (draft.correct === i) draft.correct = 0;\n        paint();\n      };\n    });\n    var addBtn = host.querySelector('#addOpt');\n    if (addBtn) addBtn.onclick = function(){ draft.options.push(''); paint(); };\n    if (isImage){\n      var mediaInp = host.querySelector('#fMediaUrl');\n      if (mediaInp) mediaInp.oninput = function(){\n        draft.media = mediaInp.value.trim() ? { kind:'image', url: mediaInp.value.trim() } : null;\n      };\n    }\n  }\n  paint();\n}\n\n// ---- True/False ----\nfunction renderTrueFalse(host, draft){\n  host.innerHTML =\n    '<div class=\"fieldgroup\"><div class=\"fieldgrouphead\">Correct answer</div>' +\n    '<div class=\"optrow\"><input type=\"radio\" name=\"tfRadio\" '+(draft.correct===0?'checked':'')+' id=\"tfTrue\"><label for=\"tfTrue\" style=\"text-transform:none;font-weight:600\">True</label></div>' +\n    '<div class=\"optrow\"><input type=\"radio\" name=\"tfRadio\" '+(draft.correct===1?'checked':'')+' id=\"tfFalse\"><label for=\"tfFalse\" style=\"text-transform:none;font-weight:600\">False</label></div>' +\n    '</div>';\n  document.getElementById('tfTrue').onchange = function(){ draft.correct = 0; };\n  document.getElementById('tfFalse').onchange = function(){ draft.correct = 1; };\n}\n\n// ---- Multiple response (multiple correct answers) ----\nfunction renderOptionsMultiCorrect(host, draft){\n  function paint(){\n    var rows = draft.options.map(function(o,i){\n      var checked = draft.correct.indexOf(i) !== -1;\n      return '<div class=\"optrow\">' +\n        '<input type=\"checkbox\" '+(checked?'checked':'')+' data-i=\"'+i+'\">' +\n        '<input type=\"text\" value=\"'+escapeHtml(o)+'\" data-i=\"'+i+'\" placeholder=\"Option '+(i+1)+'\">' +\n        (draft.options.length>2 ? '<button class=\"minidelbtn\" data-i=\"'+i+'\">Remove</button>' : '') +\n      '</div>';\n    }).join('');\n    host.innerHTML =\n      '<div class=\"fieldgroup\"><div class=\"fieldgrouphead\">Answer options - check all correct ones</div>' +\n      rows +\n      (draft.options.length < 6 ? '<button class=\"miniaddbtn\" id=\"addOpt\">+ Add option</button>' : '') +\n      '</div>';\n    Array.prototype.forEach.call(host.querySelectorAll('input[type=checkbox]'), function(cb){\n      cb.onchange = function(){\n        var i = +cb.getAttribute('data-i');\n        var idx = draft.correct.indexOf(i);\n        if (cb.checked && idx === -1) draft.correct.push(i);\n        if (!cb.checked && idx !== -1) draft.correct.splice(idx,1);\n      };\n    });\n    Array.prototype.forEach.call(host.querySelectorAll('input[type=text][data-i]'), function(inp){\n      inp.oninput = function(){ draft.options[+inp.getAttribute('data-i')] = inp.value; };\n    });\n    Array.prototype.forEach.call(host.querySelectorAll('.minidelbtn'), function(btn){\n      btn.onclick = function(){\n        var i = +btn.getAttribute('data-i');\n        draft.options.splice(i,1);\n        draft.correct = draft.correct.filter(function(c){ return c!==i; }).map(function(c){ return c>i?c-1:c; });\n        paint();\n      };\n    });\n    var addBtn = host.querySelector('#addOpt');\n    if (addBtn) addBtn.onclick = function(){ draft.options.push(''); paint(); };\n  }\n  paint();\n}\n\n// ---- Rating scale (ungraded) ----\nfunction renderRatingFields(host, draft){\n  host.innerHTML =\n    '<div class=\"fieldgroup\"><div class=\"fieldgrouphead\">Scale settings</div>' +\n    '<label>Minimum value</label><input type=\"text\" id=\"fMin\" value=\"'+draft.scale.min+'\">' +\n    '<label>Maximum value</label><input type=\"text\" id=\"fMax\" value=\"'+draft.scale.max+'\">' +\n    '<label>Label for minimum (optional)</label><input type=\"text\" id=\"fMinLbl\" value=\"'+escapeHtml(draft.scale.minLabel)+'\">' +\n    '<label>Label for maximum (optional)</label><input type=\"text\" id=\"fMaxLbl\" value=\"'+escapeHtml(draft.scale.maxLabel)+'\">' +\n    '</div>';\n  document.getElementById('fMin').oninput = function(e){ draft.scale.min = parseInt(e.target.value)||1; };\n  document.getElementById('fMax').oninput = function(e){ draft.scale.max = parseInt(e.target.value)||5; };\n  document.getElementById('fMinLbl').oninput = function(e){ draft.scale.minLabel = e.target.value; };\n  document.getElementById('fMaxLbl').oninput = function(e){ draft.scale.maxLabel = e.target.value; };\n}\n\n// ---- Ranking (admin enters items already in correct order) ----\nfunction renderRankingFields(host, draft){\n  function paint(){\n    var rows = draft.items.map(function(o,i){\n      return '<div class=\"optrow\"><span style=\"width:22px;font-weight:900;color:var(--navy)\">'+(i+1)+'.</span>' +\n        '<input type=\"text\" value=\"'+escapeHtml(o)+'\" data-i=\"'+i+'\" placeholder=\"Item '+(i+1)+'\">' +\n        (draft.items.length>2 ? '<button class=\"minidelbtn\" data-i=\"'+i+'\">Remove</button>' : '') +\n      '</div>';\n    }).join('');\n    host.innerHTML =\n      '<div class=\"fieldgroup\"><div class=\"fieldgrouphead\">Items, entered in their CORRECT order (participants will see them shuffled)</div>' +\n      rows +\n      (draft.items.length < 6 ? '<button class=\"miniaddbtn\" id=\"addItem\">+ Add item</button>' : '') +\n      '</div>';\n    Array.prototype.forEach.call(host.querySelectorAll('input[type=text][data-i]'), function(inp){\n      inp.oninput = function(){ draft.items[+inp.getAttribute('data-i')] = inp.value; };\n    });\n    Array.prototype.forEach.call(host.querySelectorAll('.minidelbtn'), function(btn){\n      btn.onclick = function(){ draft.items.splice(+btn.getAttribute('data-i'),1); paint(); };\n    });\n    var addBtn = host.querySelector('#addItem');\n    if (addBtn) addBtn.onclick = function(){ draft.items.push(''); paint(); };\n  }\n  paint();\n  // correctOrder is always the identity of the stored (already-correct) order\n  draft.correctOrder = draft.items.map(function(_,i){ return i; });\n}\n\n// ---- Matching (admin enters right column already aligned to left) ----\nfunction renderMatchingFields(host, draft){\n  function paint(){\n    var rows = draft.items.map(function(left,i){\n      return '<div class=\"optrow\">' +\n        '<input type=\"text\" value=\"'+escapeHtml(left)+'\" data-side=\"left\" data-i=\"'+i+'\" placeholder=\"Left '+(i+1)+'\">' +\n        '<span style=\"color:var(--grey)\">\\u2194</span>' +\n        '<input type=\"text\" value=\"'+escapeHtml(draft.matchRight[i]||'')+'\" data-side=\"right\" data-i=\"'+i+'\" placeholder=\"Matches left '+(i+1)+'\">' +\n        (draft.items.length>2 ? '<button class=\"minidelbtn\" data-i=\"'+i+'\">Remove</button>' : '') +\n      '</div>';\n    }).join('');\n    host.innerHTML =\n      '<div class=\"fieldgroup\"><div class=\"fieldgrouphead\">Enter matching pairs, left and right already correctly aligned</div>' +\n      rows +\n      (draft.items.length < 6 ? '<button class=\"miniaddbtn\" id=\"addPair\">+ Add pair</button>' : '') +\n      '</div>';\n    Array.prototype.forEach.call(host.querySelectorAll('input[data-side=left]'), function(inp){\n      inp.oninput = function(){ draft.items[+inp.getAttribute('data-i')] = inp.value; };\n    });\n    Array.prototype.forEach.call(host.querySelectorAll('input[data-side=right]'), function(inp){\n      inp.oninput = function(){ draft.matchRight[+inp.getAttribute('data-i')] = inp.value; };\n    });\n    Array.prototype.forEach.call(host.querySelectorAll('.minidelbtn'), function(btn){\n      btn.onclick = function(){\n        var i = +btn.getAttribute('data-i');\n        draft.items.splice(i,1); draft.matchRight.splice(i,1); paint();\n      };\n    });\n    var addBtn = host.querySelector('#addPair');\n    if (addBtn) addBtn.onclick = function(){ draft.items.push(''); draft.matchRight.push(''); paint(); };\n  }\n  paint();\n  draft.correctPairs = draft.items.map(function(_,i){ return [i,i]; });\n}\n\n// ---- Drag & drop (items + zones + a zone-picker per item) ----\nfunction renderDragDropFields(host, draft){\n  function paint(){\n    var zoneOptions = draft.dropZones.map(function(z,zi){ return '<option value=\"'+zi+'\">'+ (z||('Zone '+(zi+1))) +'</option>'; }).join('');\n    var itemRows = draft.items.map(function(it,i){\n      var currentZone = (draft.correctPlacement && draft.correctPlacement[i]) ? draft.correctPlacement[i].zone : 0;\n      return '<div class=\"optrow\">' +\n        '<input type=\"text\" value=\"'+escapeHtml(it)+'\" data-item-i=\"'+i+'\" placeholder=\"Item '+(i+1)+'\">' +\n        '<select class=\"zonepicker\" data-zone-for=\"'+i+'\" style=\"max-width:140px;margin:0\">'+\n          draft.dropZones.map(function(z,zi){ return '<option value=\"'+zi+'\"'+(zi===currentZone?' selected':'')+'>'+(z||('Zone '+(zi+1)))+'</option>'; }).join('') +\n        '</select>' +\n        (draft.items.length>2 ? '<button class=\"minidelbtn\" data-item-del=\"'+i+'\">Remove</button>' : '') +\n      '</div>';\n    }).join('');\n    var zoneRows = draft.dropZones.map(function(z,i){\n      return '<div class=\"optrow\">' +\n        '<input type=\"text\" value=\"'+escapeHtml(z)+'\" data-zone-i=\"'+i+'\" placeholder=\"Zone label '+(i+1)+'\">' +\n        (draft.dropZones.length>1 ? '<button class=\"minidelbtn\" data-zone-del=\"'+i+'\">Remove</button>' : '') +\n      '</div>';\n    }).join('');\n    host.innerHTML =\n      '<div class=\"fieldgroup\"><div class=\"fieldgrouphead\">Drop zones</div>' + zoneRows +\n      '<button class=\"miniaddbtn\" id=\"addZone\">+ Add zone</button></div>' +\n      '<div class=\"fieldgroup\"><div class=\"fieldgrouphead\">Draggable items and their correct zone</div>' + itemRows +\n      (draft.items.length < 6 ? '<button class=\"miniaddbtn\" id=\"addItem\">+ Add item</button>' : '') +\n      '</div>';\n\n    Array.prototype.forEach.call(host.querySelectorAll('[data-zone-i]'), function(inp){\n      inp.oninput = function(){ draft.dropZones[+inp.getAttribute('data-zone-i')] = inp.value; paint(); };\n    });\n    Array.prototype.forEach.call(host.querySelectorAll('[data-zone-del]'), function(btn){\n      btn.onclick = function(){\n        var zi = +btn.getAttribute('data-zone-del');\n        draft.dropZones.splice(zi,1);\n        draft.correctPlacement = (draft.correctPlacement||[]).map(function(p){\n          return { item:p.item, zone: p.zone===zi?0:(p.zone>zi?p.zone-1:p.zone) };\n        });\n        paint();\n      };\n    });\n    var addZoneBtn = host.querySelector('#addZone');\n    if (addZoneBtn) addZoneBtn.onclick = function(){ draft.dropZones.push(''); paint(); };\n\n    Array.prototype.forEach.call(host.querySelectorAll('[data-item-i]'), function(inp){\n      inp.oninput = function(){ draft.items[+inp.getAttribute('data-item-i')] = inp.value; };\n    });\n    Array.prototype.forEach.call(host.querySelectorAll('[data-zone-for]'), function(sel){\n      sel.onchange = function(){\n        var i = +sel.getAttribute('data-zone-for');\n        if (!draft.correctPlacement) draft.correctPlacement = draft.items.map(function(_,ii){ return {item:ii,zone:0}; });\n        var entry = draft.correctPlacement.find(function(p){ return p.item===i; });\n        if (entry) entry.zone = +sel.value;\n      };\n    });\n    Array.prototype.forEach.call(host.querySelectorAll('[data-item-del]'), function(btn){\n      btn.onclick = function(){\n        var i = +btn.getAttribute('data-item-del');\n        draft.items.splice(i,1);\n        draft.correctPlacement = (draft.correctPlacement||[]).filter(function(p){ return p.item!==i; })\n          .map(function(p){ return { item: p.item>i?p.item-1:p.item, zone:p.zone }; });\n        paint();\n      };\n    });\n  }\n  if (!draft.correctPlacement || draft.correctPlacement.length !== draft.items.length){\n    draft.correctPlacement = draft.items.map(function(_,i){ return {item:i, zone:0}; });\n  }\n  paint();\n}\n\n// ---- Client-side pre-save validation (mirrors bank.js server-side rules,\n// giving instant feedback before the round trip to the server) ----\nfunction validateDraftClientSide(q){\n  if (!q.text || !q.text.trim()) return 'Question text is required.';\n  switch (q.type) {\n    case 'mc': case 'image': case 'multi':\n      if (!q.options || q.options.some(function(o){ return !o.trim(); })) return 'All answer options must have text.';\n      if (q.type !== 'multi' && (q.correct===undefined || q.correct===null)) return 'Please select the correct answer.';\n      if (q.type === 'multi' && (!q.correct || q.correct.length===0)) return 'Please check at least one correct answer.';\n      break;\n    case 'ranking': case 'dragdrop':\n      if (!q.items || q.items.some(function(o){ return !o.trim(); })) return 'All items must have text.';\n      break;\n    case 'matching':\n      if (!q.items || q.items.some(function(o){ return !o.trim(); })) return 'All left-side items must have text.';\n      if (!q.matchRight || q.matchRight.some(function(o){ return !o.trim(); })) return 'All right-side matches must have text.';\n      break;\n    case 'rating':\n      if (q.scale.min >= q.scale.max) return 'Maximum must be greater than minimum.';\n      break;\n  }\n  return null;\n}\n\n\n// ============================================================\n// Run Session view: launches questions FROM THE SAVED BANK over\n// the existing SessionRoom WebSocket, shows live per-type response\n// monitoring, and drives the corrected Next Question flow (loads\n// into a PREVIEW - never auto-launches - admin must click Launch\n// each time, so every question is reviewable/skippable).\n// ============================================================\n\nvar runState = { bankQuestions: [], currentIndex: 0, sessionCode: '', ws: null, reconnectDelay: 1000, liveState: null };\n\nfunction initRunSession(code, bankQuestions){\n  runState.sessionCode = code;\n  runState.bankQuestions = bankQuestions;\n  runState.currentIndex = 0;\n  connectSessionSocket();\n  showQuestionPreview(0);\n}\n\nfunction connectSessionSocket(){\n  var proto = location.protocol === 'https:' ? 'wss:' : 'ws:';\n  runState.ws = new WebSocket(proto + '//' + location.host + '/ws?code=' + encodeURIComponent(runState.sessionCode) + '&role=admin');\n  runState.ws.onopen = function(){ runState.reconnectDelay = 1000; setConnPill(true, 'Live \\u00b7 Connected'); };\n  runState.ws.onmessage = function(evt){\n    var msg; try { msg = JSON.parse(evt.data); } catch(e){ return; }\n    if (msg.kind === 'state') { runState.liveState = msg.state; renderLiveSession(); }\n  };\n  runState.ws.onclose = function(){\n    setConnPill(false, 'Reconnecting\\u2026');\n    setTimeout(connectSessionSocket, runState.reconnectDelay);\n    runState.reconnectDelay = Math.min(runState.reconnectDelay*1.6, 8000);\n  };\n  runState.ws.onerror = function(){ try{ runState.ws.close(); }catch(e){} };\n}\n\nfunction sendWs(obj){ if (runState.ws && runState.ws.readyState === 1) runState.ws.send(JSON.stringify(obj)); }\n\nfunction totalQuestions(){ return runState.bankQuestions.length; }\nfunction isLastQuestion(){ return runState.currentIndex >= totalQuestions() - 1; }\n\n// ---- Preview screen: shows the upcoming question, admin reviews then clicks Launch ----\nfunction showQuestionPreview(index){\n  runState.currentIndex = index;\n  var q = runState.bankQuestions[index];\n  document.getElementById('runSetup').classList.remove('hide');\n  document.getElementById('runLive').classList.add('hide');\n  document.getElementById('runQCounter').textContent = 'Question ' + (index+1) + ' of ' + totalQuestions();\n  document.getElementById('runQPreview').innerHTML = buildQuestionPreviewHtml(q);\n}\n\nfunction buildQuestionPreviewHtml(q){\n  var badge = '<span class=\"qtypebadge qtb-'+q.type+'\">'+(TYPE_LABELS[q.type]||q.type)+'</span>';\n  var body = '<div class=\"qpreviewcard\">' + badge + '<h2 style=\"margin-top:10px\">'+escapeHtml(q.text)+'</h2>';\n  switch (q.type) {\n    case 'mc': case 'image':\n      body += '<ol class=\"qpreviewlist\">' + q.options.map(function(o,i){\n        return '<li>'+(i===q.correct?'<b>':'')+escapeHtml(o)+(i===q.correct?' \\u2713 correct</b>':'')+'</li>';\n      }).join('') + '</ol>';\n      break;\n    case 'tf':\n      body += '<p class=\"muted\">Correct answer: <b>'+(q.correct===0?'True':'False')+'</b></p>';\n      break;\n    case 'multi':\n      body += '<ol class=\"qpreviewlist\">' + q.options.map(function(o,i){\n        var isCorrect = q.correct.indexOf(i) !== -1;\n        return '<li>'+(isCorrect?'<b>':'')+escapeHtml(o)+(isCorrect?' \\u2713</b>':'')+'</li>';\n      }).join('') + '</ol>';\n      break;\n    case 'rating':\n      body += '<p class=\"muted\">Scale '+q.scale.min+' ('+escapeHtml(q.scale.minLabel||'')+') to '+q.scale.max+' ('+escapeHtml(q.scale.maxLabel||'')+') \\u2014 ungraded feedback</p>';\n      break;\n    case 'text':\n      body += '<p class=\"muted\">Open text response \\u2014 ungraded</p>';\n      break;\n    case 'wordcloud':\n      body += '<p class=\"muted\">Word cloud response \\u2014 ungraded</p>';\n      break;\n    case 'ranking':\n      body += '<p class=\"muted\">Correct order:</p><ol class=\"qpreviewlist\">' + q.items.map(function(o){ return '<li>'+escapeHtml(o)+'</li>'; }).join('') + '</ol>';\n      break;\n    case 'matching':\n      body += '<p class=\"muted\">Correct pairs:</p><ol class=\"qpreviewlist\">' + q.items.map(function(o,i){\n        return '<li>'+escapeHtml(o)+' \\u2194 '+escapeHtml(q.matchRight[i])+'</li>';\n      }).join('') + '</ol>';\n      break;\n    case 'dragdrop':\n      body += '<p class=\"muted\">Correct placements:</p><ol class=\"qpreviewlist\">' + q.correctPlacement.map(function(p){\n        return '<li>'+escapeHtml(q.items[p.item])+' \\u2192 '+escapeHtml(q.dropZones[p.zone])+'</li>';\n      }).join('') + '</ol>';\n      break;\n  }\n  body += '<p class=\"muted\" style=\"margin-top:8px\">Duration: '+q.duration+'s</p></div>';\n  return body;\n}\n\ndocument.getElementById('launchFromBank').onclick = function(){\n  var q = runState.bankQuestions[runState.currentIndex];\n  sendWs({ type:'launch', question: q });\n};\n\ndocument.getElementById('skipQuestion').onclick = function(){\n  if (!isLastQuestion()) showQuestionPreview(runState.currentIndex + 1);\n};\n\ndocument.getElementById('revealBtn').onclick = function(){ sendWs({ type:'reveal' }); };\ndocument.getElementById('nextQuestionBtn').onclick = function(){\n  if (!isLastQuestion()){\n    showQuestionPreview(runState.currentIndex + 1);\n  }\n};\ndocument.getElementById('showLeaderboardBtn').onclick = function(){ sendWs({ type:'showBoard' }); };\ndocument.getElementById('finaleBtn').onclick = function(){ sendWs({ type:'finale' }); };\ndocument.getElementById('resetSessionBtn').onclick = function(){\n  sendWs({ type:'reset' });\n  showQuestionPreview(0);\n};\n\n// ---- Live monitoring while a question is running ----\nfunction renderLiveSession(){\n  var s = runState.liveState;\n  if (!s) return;\n  document.getElementById('pc').textContent = Object.keys(s.participants).length;\n  document.getElementById('ac').textContent = Object.keys(s.answers||{}).length;\n\n  var isLive = s.phase === 'live';\n  document.getElementById('runSetup').classList.toggle('hide', isLive);\n  document.getElementById('runLive').classList.toggle('hide', !isLive);\n\n  if (isLive && s.question){\n    document.getElementById('liveQCounter').textContent = 'Question ' + (runState.currentIndex+1) + ' of ' + totalQuestions();\n    document.getElementById('liveQText').textContent = s.question.text;\n    renderResponseDistribution(s);\n    startAdminTimer(s.question);\n\n    var isLast = isLastQuestion();\n    document.getElementById('preRevealRow').classList.toggle('hide', !!s.reveal);\n    document.getElementById('postRevealRow').classList.toggle('hide', !s.reveal);\n    document.getElementById('nextQuestionBtn').classList.toggle('hide', !!(s.reveal && isLast));\n    document.getElementById('finaleBtn').classList.toggle('hide', !(s.reveal && isLast));\n  }\n  renderLeaderboardList(s);\n}\n\nfunction renderResponseDistribution(s){\n  var q = s.question;\n  var host = document.getElementById('dist');\n  var answers = Object.values(s.answers || {});\n  var graded = ['mc','tf','multi','image'].indexOf(q.type) !== -1;\n\n  if (q.type === 'mc' || q.type === 'tf' || q.type === 'image'){\n    var counts = q.options.map(function(_,i){ return answers.filter(function(a){ return a.option===i; }).length; });\n    var max = Math.max(1, Math.max.apply(null, counts));\n    var colors = ['#0000FF','#00A2FF','#FEDA00','#09BC09','#6A4CF5','#E0527A'];\n    host.innerHTML = q.options.map(function(o,i){\n      return '<div style=\"margin:10px 0\"><div style=\"display:flex;justify-content:space-between;font-size:12.5px;font-weight:800;color:#0E1540\"><span>'+String.fromCharCode(65+i)+'. '+escapeHtml(o)+'</span><span>'+counts[i]+'</span></div>' +\n        '<div style=\"height:10px;background:#EDEFF7;border-radius:8px;overflow:hidden;margin-top:4px\"><div style=\"height:100%;width:'+(counts[i]/max*100)+'%;background:'+colors[i%colors.length]+'\"></div></div></div>';\n    }).join('');\n  } else if (q.type === 'multi'){\n    var counts2 = q.options.map(function(_,i){ return answers.filter(function(a){ return a.options && a.options.indexOf(i)!==-1; }).length; });\n    var max2 = Math.max(1, Math.max.apply(null, counts2));\n    host.innerHTML = q.options.map(function(o,i){\n      return '<div style=\"margin:10px 0\"><div style=\"display:flex;justify-content:space-between;font-size:12.5px;font-weight:800;color:#0E1540\"><span>'+escapeHtml(o)+'</span><span>'+counts2[i]+'</span></div>' +\n        '<div style=\"height:10px;background:#EDEFF7;border-radius:8px;overflow:hidden;margin-top:4px\"><div style=\"height:100%;width:'+(counts2[i]/max2*100)+'%;background:#6A4CF5\"></div></div></div>';\n    }).join('');\n  } else if (q.type === 'rating'){\n    var buckets = {};\n    for (var v=q.scale.min; v<=q.scale.max; v++) buckets[v]=0;\n    answers.forEach(function(a){ if (buckets[a.value]!==undefined) buckets[a.value]++; });\n    var maxR = Math.max(1, Math.max.apply(null, Object.values(buckets)));\n    host.innerHTML = '<div style=\"display:flex;gap:8px;align-items:flex-end;height:100px;margin-top:8px\">' +\n      Object.keys(buckets).map(function(k){\n        var h = Math.round(buckets[k]/maxR*80)+10;\n        return '<div style=\"flex:1;text-align:center\"><div style=\"height:'+h+'px;background:#FF8A3D;border-radius:6px 6px 0 0\"></div><div style=\"font-size:10px;font-weight:800;margin-top:4px\">'+k+'</div></div>';\n      }).join('') + '</div>';\n  } else if (q.type === 'text' || q.type === 'wordcloud'){\n    host.innerHTML = '<div style=\"display:flex;flex-wrap:wrap;gap:8px;margin-top:8px\">' +\n      answers.map(function(a){\n        return '<span style=\"background:#EEF1FF;color:var(--blue);padding:6px 12px;border-radius:999px;font-size:12px;font-weight:700\">'+escapeHtml(a.text)+'</span>';\n      }).join('') + '</div>' +\n      '<p class=\"muted\" style=\"margin-top:8px\">'+answers.length+' response'+(answers.length===1?'':'s')+' submitted</p>';\n  } else {\n    host.innerHTML = '<p class=\"muted\" style=\"margin-top:8px\">'+answers.length+' of '+Object.keys(s.participants).length+' participants have answered.</p>';\n  }\n}\n\nvar adminTimerInterval;\nfunction startAdminTimer(question){\n  clearInterval(adminTimerInterval);\n  var d = question.duration, end = question.started + d*1000;\n  var circumference = 2 * Math.PI * 52;\n  var ringEl = document.getElementById('ringProgress');\n  var numEl = document.getElementById('ringNum');\n  adminTimerInterval = setInterval(function(){\n    var left = Math.max(0, end - Date.now());\n    var pct = left/(d*1000);\n    if (ringEl){\n      var dash = circumference*pct;\n      ringEl.setAttribute('stroke-dasharray', dash.toFixed(1)+' '+(circumference-dash).toFixed(1));\n    }\n    if (numEl) numEl.textContent = left ? Math.ceil(left/1000) : '0';\n    if (!left) clearInterval(adminTimerInterval);\n  }, 100);\n}\n\nfunction renderLeaderboardList(s){\n  var arr = Object.values(s.participants).sort(function(a,b){ return (b.score||0)-(a.score||0); });\n  var el = document.getElementById('leader');\n  if (!el) return;\n  el.innerHTML = arr.map(function(p,i){\n    var rankCls = i===0?'r1':(i===1?'r2':(i===2?'r3':''));\n    var rowCls = i===0?'top1':'';\n    return '<li class=\"lrow '+rowCls+'\"><span class=\"lrank '+rankCls+'\">'+(i+1)+'</span>' +\n      '<span class=\"avmini\">'+avatarImg(p.avatar||'robot')+'</span>' +\n      '<span class=\"lname\">'+escapeHtml(p.name)+'</span>' +\n      '<span><div class=\"lscore\">'+(p.score||0)+'</div>'+(p.lastDelta?'<div class=\"ldelta\">+'+p.lastDelta+'</div>':'')+'</span></li>';\n  }).join('');\n  document.getElementById('lb').classList.toggle('hide', !s.showBoard);\n}\n" + '</' + 'script>' + "\n</body></html>\n";
}

function participantHtml() {
  var avatarScript = '<script>var AVATAR_DATA = ' + JSON.stringify(AVATAR_DATA) + ';</' + 'script>';
  return "<!doctype html>\n<html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Join Live Quiz</title>\n<style>\n:root{--blue:#0000FF;--sky:#00A2FF;--neon:#CFF91C;--yellow:#FEDA00;--green:#09BC09;--navy:#0E1540;--ink:#1A1E36;--grey:#929292;--bg:#F6F7FB}\n*{box-sizing:border-box}\nbody{margin:0;font-family:Arial,Helvetica,sans-serif;color:var(--ink);background:var(--bg);position:relative;min-height:100vh}\n.bgwrap{position:fixed;inset:0;z-index:0;background-image:url('data:image/webp;base64,');background-size:cover;background-position:center top;background-repeat:no-repeat}\n.top{height:6px;background:linear-gradient(90deg,var(--blue),var(--neon));position:relative;z-index:1}\nheader{padding:18px 24px;display:flex;justify-content:flex-end;align-items:center;position:relative;z-index:1;flex-wrap:wrap;gap:8px}\n.pill{border-radius:999px;padding:6px 14px;font-size:11px;font-weight:800;background:#ECFFEC;color:#067806}\n.wrap{max-width:760px;margin:0 auto;padding:20px 18px 60px;position:relative;z-index:1}\n.gcard{background:rgba(255,255,255,.82);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);border:1px solid rgba(255,255,255,.9);border-radius:26px;padding:26px;box-shadow:0 12px 34px rgba(14,21,64,.14);margin-bottom:18px}\nh1,h2{margin:0 0 6px;color:var(--navy)}\nh1{font-size:22px;font-weight:900}\nh2{font-size:19px;font-weight:900}\n.gtitle{font-size:26px;font-weight:900;background:linear-gradient(90deg,var(--blue),var(--neon));-webkit-background-clip:text;background-clip:text;color:transparent;margin:0}\n.center{text-align:center}\n.muted{color:var(--grey);font-size:12.5px}\n.hide{display:none!important}\nbutton,input,select,textarea{font:inherit}\nbutton{border:0;border-radius:16px;padding:13px 18px;font-weight:800;cursor:pointer;transition:transform .12s ease}\nbutton:active{transform:scale(.97)}\n.gbtn{background:var(--blue);color:#fff;width:100%;box-shadow:0 8px 18px rgba(0,0,255,.22)}\n.secbtn{background:#EEF1FF;color:var(--blue)}\ninput,textarea{width:100%;padding:13px 14px;border:1.5px solid #E1E5F2;border-radius:14px;margin:6px 0 14px;background:rgba(255,255,255,.9);resize:none;overflow:hidden;line-height:1.4}\nlabel{font-weight:800;font-size:11.5px;color:var(--navy);text-transform:uppercase;letter-spacing:.3px}\n.msg{display:none;border-radius:12px;padding:9px 12px;margin:6px 0 12px;font-size:12.5px;font-weight:700}\n.msg.show{display:block}\n.msg.err{background:#FFECEC;color:#B50000}\n.msg.info{background:#EAF3FF;color:#0000FF}\n\n.avgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:16px 0}\n.avitem{display:flex;flex-direction:column;align-items:center;gap:6px;cursor:pointer}\n.avorb{width:56px;height:56px;border-radius:50%;display:flex;align-items:center;justify-content:center;border:3px solid transparent;box-shadow:0 4px 10px rgba(14,21,64,.10);transition:transform .15s,border-color .15s}\n.avorb img{width:70%;height:70%;object-fit:contain}\n.avitem.selected .avorb{border-color:var(--blue);transform:scale(1.08);box-shadow:0 0 0 4px rgba(0,0,255,.15)}\n.avlabel{font-size:9.5px;font-weight:800;color:var(--navy);text-transform:uppercase;letter-spacing:.2px}\n.avmini{width:36px;height:36px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0}\n.avmini img{width:70%;height:70%;object-fit:contain}\n.code{font-size:34px;letter-spacing:6px;font-weight:900;background:linear-gradient(90deg,var(--blue),var(--neon));-webkit-background-clip:text;background-clip:text;color:transparent}\n\n.ringwrap{display:flex;justify-content:center;margin:20px 0}\n.ring{position:relative;width:120px;height:120px}\n.ring svg{transform:rotate(-90deg)}\n.ring .num{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center}\n.ring .num b{font-size:30px;color:var(--navy);line-height:1}\n.ring .num span{font-size:9px;color:var(--grey);font-weight:800;letter-spacing:.5px}\n\n.answers{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:8px}\n.answer{position:relative;min-height:64px;border-radius:16px;padding:14px 16px 14px 46px;text-align:left;background:rgba(255,255,255,.92);color:var(--ink);font-weight:700;font-size:13.5px;line-height:1.25;border:2px solid #E7EAF3;box-shadow:0 4px 12px rgba(14,21,64,.08)}\n.answer[data-i=\"0\"]{border-left:5px solid var(--blue)}\n.answer[data-i=\"1\"]{border-left:5px solid var(--sky)}\n.answer[data-i=\"2\"]{border-left:5px solid var(--yellow)}\n.answer[data-i=\"3\"]{border-left:5px solid var(--green)}\n.answer[data-i=\"4\"]{border-left:5px solid #6A4CF5}\n.answer[data-i=\"5\"]{border-left:5px solid #E0527A}\n.answer .letter{position:absolute;left:12px;top:50%;transform:translateY(-50%);width:24px;height:24px;border-radius:50%;background:rgba(0,0,0,.06);display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:900;color:var(--navy)}\n.answer.selected{border-color:#1A1E36;box-shadow:0 0 0 3px rgba(26,30,54,.18)}\n.answer.selected::after{content:'Selected';position:absolute;top:6px;right:10px;font-size:9px;font-weight:900;background:var(--navy);color:#fff;padding:2px 7px;border-radius:999px}\n.answer[disabled]{opacity:.6;cursor:default}\n\n.basepts{font-size:22px;color:var(--blue);font-weight:900;margin-top:6px}\n.bonus{font-size:44px;font-weight:900;color:var(--green);animation:pop .5s ease-out}\n@keyframes pop{0%{transform:scale(.3);opacity:0}70%{transform:scale(1.15)}100%{transform:scale(1);opacity:1}}\n.rankline{font-size:16px;font-weight:800;color:var(--navy);margin-top:6px}\n\n.leader{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:10px}\n.lrow{display:grid;grid-template-columns:30px 36px 1fr auto;gap:10px;align-items:center;background:rgba(255,255,255,.85);border-radius:16px;padding:11px 14px;box-shadow:0 4px 10px rgba(14,21,64,.08)}\n.lrow.top1{background:#FFFDEC;box-shadow:0 6px 16px rgba(254,218,0,.25);border:1.5px solid #FEDA00}\n.lrank{width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:12.5px;background:#DDE2EE;color:var(--navy)}\n.lrank.r1{background:var(--yellow);color:#1A1E36}\n.lrank.r2{background:var(--sky);color:#fff}\n.lrank.r3{background:var(--green);color:#fff}\n.lname{font-weight:800;font-size:13.5px;color:var(--navy)}\n.lfastest{font-size:9.5px;font-weight:800;color:var(--green);display:flex;align-items:center;gap:3px;margin-top:1px}\n.lscore{font-weight:900;font-size:15px;color:var(--navy);text-align:right}\n.ldelta{font-size:11px;font-weight:900;color:var(--green);text-align:right}\n\n.dotpulse{display:flex;gap:7px;justify-content:center;margin-top:14px}\n.dotpulse span{width:9px;height:9px;border-radius:50%;background:var(--blue);animation:dotanim 1.2s infinite ease-in-out}\n.dotpulse span:nth-child(2){animation-delay:.2s;background:var(--sky)}\n.dotpulse span:nth-child(3){animation-delay:.4s;background:var(--green)}\n@keyframes dotanim{0%,80%,100%{transform:scale(.6);opacity:.4}40%{transform:scale(1);opacity:1}}\n\n.confetti-piece{position:fixed;top:-20px;pointer-events:none;z-index:5;border-radius:2px}\n@keyframes confettiFall{to{transform:translateY(110vh) rotate(360deg);opacity:0}}\n\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:14px}\n\n@media(max-width:480px){\n  .avgrid{grid-template-columns:repeat(4,1fr);gap:10px}\n  .avorb{width:48px;height:48px}\n  .answers{grid-template-columns:1fr}\n  .grid2{grid-template-columns:1fr}\n  .ring{width:100px;height:100px}\n  .ring .num b{font-size:24px}\n  .gtitle{font-size:22px}\n  .bonus{font-size:36px}\n}\n\n.intermission-overlay{position:fixed;inset:0;z-index:20;display:flex;align-items:center;justify-content:center;background:rgba(246,247,251,.88);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px)}.intermission-card{background:rgba(255,255,255,.92);border-radius:28px;padding:40px 36px;text-align:center;box-shadow:0 16px 40px rgba(14,21,64,.18);max-width:340px;animation:im-pop .4s ease-out}.intermission-phrase{font-size:19px;font-weight:900;color:var(--navy);margin-top:16px}@keyframes im-pop{0%{transform:scale(.85);opacity:0}100%{transform:scale(1);opacity:1}}.ig-bounce{animation:ig-bounce-kf 0.9s infinite ease-in-out}@keyframes ig-bounce-kf{0%,100%{transform:translateY(0)}50%{transform:translateY(-18px)}}.ig-spin{animation:ig-spin-kf 1.6s linear infinite;transform-origin:60px 60px}.ig-spin-slow{animation:ig-spin-kf 3s linear infinite;transform-origin:60px 60px}@keyframes ig-spin-kf{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}.ig-pulse{animation:ig-pulse-kf 1.6s infinite ease-out;transform-origin:60px 60px}@keyframes ig-pulse-kf{0%{transform:scale(.6);opacity:1}100%{transform:scale(1.6);opacity:0}}.ig-slide{animation:ig-slide-kf 0.8s infinite ease-in-out}@keyframes ig-slide-kf{0%,100%{transform:scaleY(1)}50%{transform:scaleY(1.6) translateY(-10px)}}#finaleScreen{position:fixed;inset:0;z-index:15;overflow-y:auto;background:linear-gradient(180deg,rgba(246,247,251,.97),rgba(255,255,255,.99))}.finale-inner{max-width:720px;margin:0 auto;padding:50px 20px 60px;text-align:center}.finale-title{font-size:34px!important;margin-bottom:30px}.podium-wrap{display:flex;align-items:flex-end;justify-content:center;gap:16px;margin-bottom:20px;flex-wrap:wrap}.podium-col{display:flex;flex-direction:column;align-items:center;width:150px}.podium-avatar{width:60px;height:60px;border-radius:50%;background:rgba(255,255,255,.9);display:flex;align-items:center;justify-content:center;box-shadow:0 6px 14px rgba(14,21,64,.15);margin-bottom:8px}.podium-avatar img{width:70%;height:70%;object-fit:contain}.podium-name{font-weight:900;color:var(--navy);font-size:14px}.podium-score{font-weight:800;color:var(--grey);font-size:12px;margin-bottom:8px}.podium-block{width:100%;border-radius:14px 14px 0 0;display:flex;align-items:flex-start;justify-content:center;padding-top:10px;font-weight:900;color:#fff;font-size:18px;box-shadow:0 -4px 14px rgba(14,21,64,.12)}.podium-rank-0{background:linear-gradient(180deg,#FEDA00,#FFB800)}.podium-rank-1{background:linear-gradient(180deg,#00A2FF,#0072FF)}.podium-rank-2{background:linear-gradient(180deg,#09BC09,#068906)}.podium-msg{font-size:11.5px;color:var(--ink);margin-top:10px;line-height:1.4;padding:0 4px}.finale-personal{background:rgba(255,255,255,.85);border-radius:16px;padding:14px 18px;margin:20px auto 0;max-width:460px;font-size:13px;font-weight:600;color:var(--navy);box-shadow:0 6px 16px rgba(14,21,64,.08)}\n</style></head>\n<body>\n<div class=\"bgwrap\"></div>\n<div class=\"top\"></div>\n<header><span class=\"pill\" id=\"connpill\">Connecting</span></header>\n<main class=\"wrap\">\n\n<div class=\"gcard\" id=\"join\">\n  <h1 class=\"gtitle\">Join the Live Quiz</h1>\n  <p class=\"muted\" style=\"margin-top:6px\">Choose your avatar, enter the session code, and pick a display name</p>\n  <div class=\"avgrid\" id=\"avgrid\"></div>\n  <label>Session code</label>\n  <input id=\"codein\" maxlength=\"6\" placeholder=\"e.g. AB12CD\">\n  <label>Your display name</label>\n  <input id=\"name\" placeholder=\"Enter your name\">\n  <div class=\"msg err\" id=\"joinMsg\"></div>\n  <button class=\"gbtn\" id=\"joinbtn\">Join Session</button>\n</div>\n\n<div class=\"gcard center hide\" id=\"waiting\">\n  <div class=\"avmini\" id=\"waitAvatar\" style=\"width:64px;height:64px;margin:0 auto 12px\"></div>\n  <h2>You're in!</h2>\n  <div class=\"code\" id=\"waitCode\">------</div>\n  <p class=\"muted\">Waiting for the presenter to launch a question&hellip;</p>\n  <div class=\"dotpulse\"><span></span><span></span><span></span></div>\n</div>\n\n<div class=\"gcard hide\" id=\"quiz\">\n  <div class=\"ringwrap\"><div class=\"ring\">\n    <svg width=\"120\" height=\"120\" viewBox=\"0 0 120 120\">\n      <circle cx=\"60\" cy=\"60\" r=\"52\" fill=\"none\" stroke=\"#E7ECF5\" stroke-width=\"9\"/>\n      <circle cx=\"60\" cy=\"60\" r=\"52\" fill=\"none\" stroke=\"url(#ringGrad)\" stroke-width=\"9\" stroke-linecap=\"round\" id=\"ringProgress\"/>\n      <defs><linearGradient id=\"ringGrad\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n        <stop offset=\"0%\" stop-color=\"#CFF91C\"/><stop offset=\"100%\" stop-color=\"#09BC09\"/>\n      </linearGradient></defs>\n    </svg>\n    <div class=\"num\"><b id=\"ringNum\">--</b><span>SECONDS</span></div>\n  </div></div>\n  <h1 id=\"qview\" style=\"text-align:center\"></h1>\n  <div class=\"msg info\" id=\"quizMsg\"></div>\n  <div id=\"answerArea\"></div>\n</div>\n\n<div class=\"gcard center hide\" id=\"submitted\">\n  <h2>Answer Submitted!</h2>\n  <p class=\"muted\" id=\"submittedChoice\"></p>\n  <p class=\"muted\">Waiting for the presenter to reveal the results&hellip;</p>\n  <div class=\"dotpulse\"><span></span><span></span><span></span></div>\n</div>\n\n<div class=\"gcard center hide\" id=\"missed\">\n  <h2>Time's Up</h2>\n  <p class=\"muted\">You didn't submit an answer in time for this question.</p>\n</div>\n\n<div class=\"gcard center hide\" id=\"result\"><div id=\"resultBody\"></div></div>\n\n<div class=\"gcard hide\" id=\"lb\">\n  <h2 class=\"gtitle\" style=\"font-size:22px\">Leaderboard</h2>\n  <ol class=\"leader\" id=\"leader\" style=\"list-style:none;padding:0\"></ol>\n</div>\n\n</main>\n\n<div class=\"hide\" id=\"finaleScreen\"></div>\n<div class=\"intermission-overlay hide\" id=\"intermissionOverlay\"></div>\n\n" + avatarScript + '<script>' + "// ============================================================\n// Synthesized sound effects via Web Audio API - no audio files,\n// fully self-contained. Unlocked on first user interaction (the\n// Join Session tap) since mobile browsers block audio playback\n// before any user gesture has occurred.\n// ============================================================\nvar audioCtx = null;\nvar audioUnlocked = false;\n\nfunction unlockAudio(){\n  if (audioUnlocked) return;\n  try {\n    audioCtx = new (window.AudioContext || window.webkitAudioContext)();\n    // Play a near-silent buffer immediately to satisfy the \"must originate\n    // from a user gesture\" requirement on iOS Safari and similar browsers.\n    var buffer = audioCtx.createBuffer(1, 1, 22050);\n    var source = audioCtx.createBufferSource();\n    source.buffer = buffer;\n    source.connect(audioCtx.destination);\n    source.start(0);\n    audioUnlocked = true;\n  } catch(e){ audioUnlocked = false; }\n}\n\nfunction tone(freq, duration, type, gainPeak, delay){\n  if (!audioCtx) return;\n  var t0 = audioCtx.currentTime + (delay||0);\n  var osc = audioCtx.createOscillator();\n  var gain = audioCtx.createGain();\n  osc.type = type || 'sine';\n  osc.frequency.setValueAtTime(freq, t0);\n  gain.gain.setValueAtTime(0.0001, t0);\n  gain.gain.exponentialRampToValueAtTime(gainPeak || 0.18, t0 + 0.01);\n  gain.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);\n  osc.connect(gain);\n  gain.connect(audioCtx.destination);\n  osc.start(t0);\n  osc.stop(t0 + duration + 0.02);\n}\n\nfunction sweep(freqStart, freqEnd, duration, type, gainPeak, delay){\n  if (!audioCtx) return;\n  var t0 = audioCtx.currentTime + (delay||0);\n  var osc = audioCtx.createOscillator();\n  var gain = audioCtx.createGain();\n  osc.type = type || 'sine';\n  osc.frequency.setValueAtTime(freqStart, t0);\n  osc.frequency.exponentialRampToValueAtTime(freqEnd, t0 + duration);\n  gain.gain.setValueAtTime(0.0001, t0);\n  gain.gain.exponentialRampToValueAtTime(gainPeak || 0.18, t0 + 0.01);\n  gain.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);\n  osc.connect(gain);\n  gain.connect(audioCtx.destination);\n  osc.start(t0);\n  osc.stop(t0 + duration + 0.02);\n}\n\nvar SOUND_LIBRARY = {\n  click: function(){ tone(600, 0.08, 'sine', 0.12); },\n  tick: function(){ tone(900, 0.04, 'square', 0.06); },\n  correct: function(){\n    tone(523.25, 0.12, 'sine', 0.16, 0);   // C5\n    tone(659.25, 0.12, 'sine', 0.16, 0.1); // E5\n    tone(783.99, 0.18, 'sine', 0.18, 0.2); // G5\n  },\n  incorrect: function(){\n    sweep(300, 160, 0.35, 'sawtooth', 0.10);\n  },\n  countdown_tick: function(){ tone(440, 0.06, 'square', 0.05); },\n  reveal_drumroll: function(){\n    for (var i=0;i<8;i++) tone(180+i*4, 0.05, 'square', 0.05, i*0.07);\n  },\n  whoosh: function(){ sweep(200, 900, 0.3, 'sine', 0.08); },\n  fanfare: function(){\n    var notes = [523.25, 659.25, 783.99, 1046.5];\n    notes.forEach(function(f,i){ tone(f, 0.22, 'triangle', 0.18, i*0.14); });\n  }\n};\n\nfunction playSound(name){\n  if (!audioUnlocked || !audioCtx) return;\n  var fn = SOUND_LIBRARY[name];\n  if (fn) { try { fn(); } catch(e){} }\n}\n\n\n// ============================================================\n// Participant-side rendering + answer submission for all 10\n// question types. Each render function builds the interactive UI\n// into #answerArea and wires up a \"submit\" action that calls\n// submitAnswer(payload) - a single shared function that sends the\n// WebSocket message and shows the \"submitted\" state.\n// ============================================================\n\nfunction escapeHtml(s){\n  return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;');\n}\n\nfunction shuffleWithMap(arr){\n  // Returns { shuffled: [...values], indexMap: [...originalIndices] }\n  // so we can always translate a participant's shuffled-position choice\n  // back to the ORIGINAL index the server/admin defined as correct.\n  var indexMap = arr.map(function(_,i){ return i; });\n  for (var i = indexMap.length - 1; i > 0; i--){\n    var j = Math.floor(Math.random() * (i+1));\n    var tmp = indexMap[i]; indexMap[i] = indexMap[j]; indexMap[j] = tmp;\n  }\n  return { shuffled: indexMap.map(function(i){ return arr[i]; }), indexMap: indexMap };\n}\n\nvar participantAnswerLocalState = {}; // per-question scratch state (selections, drag state, etc.), reset each new question\n\nfunction renderAnswerUI(question, alreadyAnswered, existingAnswer){\n  var host = document.getElementById('answerArea');\n  if (alreadyAnswered){\n    renderAlreadyAnsweredSummary(host, question, existingAnswer);\n    return;\n  }\n  switch (question.type){\n    case 'mc': case 'image': renderMcAnswer(host, question); break;\n    case 'tf': renderTfAnswer(host, question); break;\n    case 'multi': renderMultiAnswer(host, question); break;\n    case 'rating': renderRatingAnswer(host, question); break;\n    case 'text': renderTextAnswer(host, question, false); break;\n    case 'wordcloud': renderTextAnswer(host, question, true); break;\n    case 'ranking': renderRankingAnswer(host, question); break;\n    case 'matching': renderMatchingAnswer(host, question); break;\n    case 'dragdrop': renderDragDropAnswer(host, question); break;\n    default: host.innerHTML = '<p class=\"muted\">Unsupported question type.</p>';\n  }\n}\n\nfunction renderAlreadyAnsweredSummary(host, question, existingAnswer){\n  host.innerHTML = ''; // the \"submitted / waiting for reveal\" card is handled by the outer render(), not here\n}\n\n// ---- Multiple choice / Image-based ----\nfunction renderMcAnswer(host, question){\n  var mediaHtml = (question.media && question.media.kind==='image' && question.media.url)\n    ? '<img src=\"'+escapeHtml(question.media.url)+'\" style=\"width:100%;border-radius:14px;margin-bottom:14px;max-height:220px;object-fit:cover\" alt=\"\">'\n    : '';\n  host.innerHTML = mediaHtml + '<div class=\"answers\" id=\"mcButtons\">' +\n    question.options.map(function(o,i){\n      return '<button type=\"button\" class=\"answer\" data-i=\"'+i+'\"><span class=\"letter\">'+String.fromCharCode(65+i)+'</span>'+escapeHtml(o)+'</button>';\n    }).join('') + '</div>';\n  Array.prototype.forEach.call(host.querySelectorAll('.answer'), function(btn){\n    btn.onclick = function(){\n      Array.prototype.forEach.call(host.querySelectorAll('.answer'), function(b){ b.setAttribute('disabled','disabled'); });\n      btn.classList.add('selected');\n      playSound('click');\n      submitAnswer({ option: +btn.getAttribute('data-i') });\n    };\n  });\n}\n\n// ---- True/False ----\nfunction renderTfAnswer(host, question){\n  host.innerHTML = '<div class=\"answers\">' +\n    '<button type=\"button\" class=\"answer\" data-i=\"0\" style=\"text-align:center;padding-left:16px\"><b>True</b></button>' +\n    '<button type=\"button\" class=\"answer\" data-i=\"1\" style=\"text-align:center;padding-left:16px\"><b>False</b></button>' +\n    '</div>';\n  Array.prototype.forEach.call(host.querySelectorAll('.answer'), function(btn){\n    btn.onclick = function(){\n      Array.prototype.forEach.call(host.querySelectorAll('.answer'), function(b){ b.setAttribute('disabled','disabled'); });\n      btn.classList.add('selected');\n      playSound('click');\n      submitAnswer({ option: +btn.getAttribute('data-i') });\n    };\n  });\n}\n\n// ---- Multiple response (checkboxes + explicit submit) ----\nfunction renderMultiAnswer(host, question){\n  participantAnswerLocalState.multiSelected = [];\n  host.innerHTML = '<div class=\"answers\" id=\"multiButtons\">' +\n    question.options.map(function(o,i){\n      return '<button type=\"button\" class=\"answer\" data-i=\"'+i+'\"><span class=\"letter\">'+String.fromCharCode(65+i)+'</span>'+escapeHtml(o)+'</button>';\n    }).join('') + '</div>' +\n    '<button class=\"gbtn\" id=\"multiSubmit\" style=\"margin-top:14px\">Submit Answer</button>';\n  Array.prototype.forEach.call(host.querySelectorAll('.answer'), function(btn){\n    btn.onclick = function(){\n      var i = +btn.getAttribute('data-i');\n      var idx = participantAnswerLocalState.multiSelected.indexOf(i);\n      if (idx === -1){ participantAnswerLocalState.multiSelected.push(i); btn.classList.add('selected'); }\n      else { participantAnswerLocalState.multiSelected.splice(idx,1); btn.classList.remove('selected'); }\n      playSound('tick');\n    };\n  });\n  document.getElementById('multiSubmit').onclick = function(){\n    if (participantAnswerLocalState.multiSelected.length === 0) return;\n    Array.prototype.forEach.call(host.querySelectorAll('.answer'), function(b){ b.setAttribute('disabled','disabled'); });\n    document.getElementById('multiSubmit').setAttribute('disabled','disabled');\n    playSound('click');\n    submitAnswer({ options: participantAnswerLocalState.multiSelected.slice() });\n  };\n}\n\n// ---- Rating scale (ungraded) ----\nfunction renderRatingAnswer(host, question){\n  var scale = question.scale;\n  var count = scale.max - scale.min + 1;\n  var buttons = '';\n  for (var v = scale.min; v <= scale.max; v++){\n    buttons += '<button type=\"button\" class=\"answer\" data-v=\"'+v+'\" style=\"min-height:56px;text-align:center;padding-left:16px;justify-content:center\"><b style=\"font-size:18px\">'+v+'</b></button>';\n  }\n  host.innerHTML =\n    (scale.minLabel || scale.maxLabel ? '<div style=\"display:flex;justify-content:space-between;font-size:11px;color:var(--grey);font-weight:700;margin-bottom:6px\"><span>'+escapeHtml(scale.minLabel||'')+'</span><span>'+escapeHtml(scale.maxLabel||'')+'</span></div>' : '') +\n    '<div class=\"answers\" style=\"grid-template-columns:repeat('+Math.min(count,5)+',1fr)\">' + buttons + '</div>';\n  Array.prototype.forEach.call(host.querySelectorAll('.answer'), function(btn){\n    btn.onclick = function(){\n      Array.prototype.forEach.call(host.querySelectorAll('.answer'), function(b){ b.setAttribute('disabled','disabled'); });\n      btn.classList.add('selected');\n      playSound('click');\n      submitAnswer({ value: +btn.getAttribute('data-v') });\n    };\n  });\n}\n\n// ---- Open text / Word cloud (ungraded) ----\nfunction renderTextAnswer(host, question, isWordcloud){\n  host.innerHTML =\n    '<textarea id=\"textAnswerInput\" rows=\"'+(isWordcloud?1:3)+'\" placeholder=\"'+(isWordcloud?'Type one word or short phrase...':'Type your response...')+'\" maxlength=\"200\"></textarea>' +\n    '<button class=\"gbtn\" id=\"textSubmit\">Submit</button>';\n  var ta = document.getElementById('textAnswerInput');\n  ta.oninput = function(){ ta.style.height='auto'; ta.style.height=ta.scrollHeight+'px'; };\n  document.getElementById('textSubmit').onclick = function(){\n    var val = ta.value.trim();\n    if (!val) return;\n    ta.setAttribute('disabled','disabled');\n    document.getElementById('textSubmit').setAttribute('disabled','disabled');\n    playSound('click');\n    submitAnswer({ text: val });\n  };\n}\n\n// ---- Ranking (drag to reorder, or up/down buttons for accessibility/mobile reliability) ----\nfunction renderRankingAnswer(host, question){\n  var shuffle = shuffleWithMap(question.items);\n  participantAnswerLocalState.rankingOrder = shuffle.shuffled.slice(); // current visual order (text)\n  participantAnswerLocalState.rankingIndexMap = shuffle.indexMap.slice(); // parallel array: original index for each visual slot\n\n  function paint(){\n    host.innerHTML = '<div id=\"rankList\" style=\"display:flex;flex-direction:column;gap:8px\">' +\n      participantAnswerLocalState.rankingOrder.map(function(text,i){\n        return '<div class=\"answer\" data-pos=\"'+i+'\" style=\"display:flex;align-items:center;justify-content:space-between;padding-left:16px\">' +\n          '<span>'+(i+1)+'. '+escapeHtml(text)+'</span>' +\n          '<span style=\"display:flex;gap:4px\">' +\n            '<button type=\"button\" class=\"secbtn\" data-act=\"up\" data-pos=\"'+i+'\" style=\"padding:6px 10px\" '+(i===0?'disabled':'')+'>\\u2191</button>' +\n            '<button type=\"button\" class=\"secbtn\" data-act=\"down\" data-pos=\"'+i+'\" style=\"padding:6px 10px\" '+(i===participantAnswerLocalState.rankingOrder.length-1?'disabled':'')+'>\\u2193</button>' +\n          '</span></div>';\n      }).join('') +\n      '</div><button class=\"gbtn\" id=\"rankSubmit\" style=\"margin-top:14px\">Submit Order</button>';\n\n    Array.prototype.forEach.call(host.querySelectorAll('[data-act]'), function(btn){\n      btn.onclick = function(){\n        var pos = +btn.getAttribute('data-pos');\n        var act = btn.getAttribute('data-act');\n        var swapWith = act === 'up' ? pos-1 : pos+1;\n        if (swapWith < 0 || swapWith >= participantAnswerLocalState.rankingOrder.length) return;\n        var arr = participantAnswerLocalState.rankingOrder;\n        var map = participantAnswerLocalState.rankingIndexMap;\n        var tmp = arr[pos]; arr[pos] = arr[swapWith]; arr[swapWith] = tmp;\n        var tmpI = map[pos]; map[pos] = map[swapWith]; map[swapWith] = tmpI;\n        playSound('tick');\n        paint();\n      };\n    });\n    document.getElementById('rankSubmit').onclick = function(){\n      Array.prototype.forEach.call(host.querySelectorAll('button'), function(b){ b.setAttribute('disabled','disabled'); });\n      playSound('click');\n      submitAnswer({ order: participantAnswerLocalState.rankingIndexMap.slice() });\n    };\n  }\n  paint();\n}\n\n// ---- Matching (tap left, then tap its match on the right) ----\nfunction renderMatchingAnswer(host, question){\n  var shuffle = shuffleWithMap(question.matchRight);\n  participantAnswerLocalState.matchingPairs = []; // [[leftOriginalIdx, rightOriginalIdx], ...]\n  participantAnswerLocalState.matchingSelectedLeft = null;\n  participantAnswerLocalState.matchingRightShuffled = shuffle.shuffled;\n  participantAnswerLocalState.matchingRightIndexMap = shuffle.indexMap;\n\n  function paint(){\n    var leftHtml = question.items.map(function(text,i){\n      var matched = participantAnswerLocalState.matchingPairs.some(function(p){ return p[0]===i; });\n      var selected = participantAnswerLocalState.matchingSelectedLeft === i;\n      return '<button type=\"button\" class=\"answer\" data-left=\"'+i+'\" style=\"text-align:center;padding-left:16px'+\n        (matched?';opacity:.5':'')+(selected?'':'')+'\" '+(matched?'disabled':'')+'>'+\n        (selected?'<b>\\u2192 </b>':'')+escapeHtml(text)+'</button>';\n    }).join('');\n    var rightHtml = participantAnswerLocalState.matchingRightShuffled.map(function(text,pos){\n      var origIdx = participantAnswerLocalState.matchingRightIndexMap[pos];\n      var matched = participantAnswerLocalState.matchingPairs.some(function(p){ return p[1]===origIdx; });\n      return '<button type=\"button\" class=\"answer\" data-right=\"'+origIdx+'\" style=\"text-align:center;padding-left:16px'+\n        (matched?';opacity:.5':'')+'\" '+(matched?'disabled':'')+'>'+escapeHtml(text)+'</button>';\n    }).join('');\n\n    host.innerHTML =\n      '<p class=\"muted\" style=\"margin-bottom:8px\">Tap an item on the left, then tap its match on the right.</p>' +\n      '<div class=\"grid2\"><div style=\"display:flex;flex-direction:column;gap:8px\">'+leftHtml+'</div>' +\n      '<div style=\"display:flex;flex-direction:column;gap:8px\">'+rightHtml+'</div></div>' +\n      '<button class=\"gbtn\" id=\"matchSubmit\" style=\"margin-top:14px\" '+(participantAnswerLocalState.matchingPairs.length===question.items.length?'':'disabled')+'>Submit Matches</button>';\n\n    Array.prototype.forEach.call(host.querySelectorAll('[data-left]'), function(btn){\n      btn.onclick = function(){\n        participantAnswerLocalState.matchingSelectedLeft = +btn.getAttribute('data-left');\n        playSound('tick');\n        paint();\n      };\n    });\n    Array.prototype.forEach.call(host.querySelectorAll('[data-right]'), function(btn){\n      btn.onclick = function(){\n        if (participantAnswerLocalState.matchingSelectedLeft === null) return;\n        var rightIdx = +btn.getAttribute('data-right');\n        participantAnswerLocalState.matchingPairs.push([participantAnswerLocalState.matchingSelectedLeft, rightIdx]);\n        participantAnswerLocalState.matchingSelectedLeft = null;\n        playSound('tick');\n        paint();\n      };\n    });\n    var submitBtn = document.getElementById('matchSubmit');\n    submitBtn.onclick = function(){\n      if (participantAnswerLocalState.matchingPairs.length !== question.items.length) return;\n      Array.prototype.forEach.call(host.querySelectorAll('button'), function(b){ b.setAttribute('disabled','disabled'); });\n      playSound('click');\n      submitAnswer({ pairs: participantAnswerLocalState.matchingPairs.slice() });\n    };\n  }\n  paint();\n}\n\n// ---- Drag & drop (tap-to-place fallback for maximum cross-device reliability:\n// real HTML5 drag events are unreliable on touch devices, so we use a\n// tap-item-then-tap-zone interaction that WORKS IDENTICALLY on both mouse\n// and touch, rather than a fragile native drag implementation) ----\nfunction renderDragDropAnswer(host, question){\n  participantAnswerLocalState.dragPlacement = []; // [{item, zone}, ...]\n  participantAnswerLocalState.dragSelectedItem = null;\n\n  function paint(){\n    var itemsHtml = question.items.map(function(text,i){\n      var placed = participantAnswerLocalState.dragPlacement.some(function(p){ return p.item===i; });\n      var selected = participantAnswerLocalState.dragSelectedItem === i;\n      return '<button type=\"button\" class=\"answer\" data-item=\"'+i+'\" style=\"text-align:center;padding-left:16px'+\n        (placed?';opacity:.4':'')+'\" '+(placed?'disabled':'')+'>'+(selected?'<b>\\u25b6 </b>':'')+escapeHtml(text)+'</button>';\n    }).join('');\n    var zonesHtml = question.dropZones.map(function(zone,zi){\n      var itemsHere = participantAnswerLocalState.dragPlacement.filter(function(p){ return p.zone===zi; }).map(function(p){ return question.items[p.item]; });\n      return '<button type=\"button\" class=\"answer\" data-zone=\"'+zi+'\" style=\"text-align:left;min-height:70px\">' +\n        '<b>'+escapeHtml(zone)+'</b>' +\n        (itemsHere.length ? '<div style=\"margin-top:6px;font-size:11.5px;font-weight:600\">' + itemsHere.map(escapeHtml).join(', ') + '</div>' : '') +\n        '</button>';\n    }).join('');\n\n    host.innerHTML =\n      '<p class=\"muted\" style=\"margin-bottom:8px\">Tap an item, then tap the zone it belongs in.</p>' +\n      '<label style=\"display:block;margin-bottom:6px\">Items</label>' +\n      '<div class=\"answers\">' + itemsHtml + '</div>' +\n      '<label style=\"display:block;margin:14px 0 6px\">Drop Zones</label>' +\n      '<div class=\"answers\">' + zonesHtml + '</div>' +\n      '<button class=\"gbtn\" id=\"dragSubmit\" style=\"margin-top:14px\" '+(participantAnswerLocalState.dragPlacement.length===question.items.length?'':'disabled')+'>Submit Placement</button>';\n\n    Array.prototype.forEach.call(host.querySelectorAll('[data-item]'), function(btn){\n      btn.onclick = function(){\n        participantAnswerLocalState.dragSelectedItem = +btn.getAttribute('data-item');\n        playSound('tick');\n        paint();\n      };\n    });\n    Array.prototype.forEach.call(host.querySelectorAll('[data-zone]'), function(btn){\n      btn.onclick = function(){\n        if (participantAnswerLocalState.dragSelectedItem === null) return;\n        var zoneIdx = +btn.getAttribute('data-zone');\n        participantAnswerLocalState.dragPlacement.push({ item: participantAnswerLocalState.dragSelectedItem, zone: zoneIdx });\n        participantAnswerLocalState.dragSelectedItem = null;\n        playSound('tick');\n        paint();\n      };\n    });\n    var submitBtn = document.getElementById('dragSubmit');\n    if (submitBtn) submitBtn.onclick = function(){\n      if (participantAnswerLocalState.dragPlacement.length !== question.items.length) return;\n      Array.prototype.forEach.call(host.querySelectorAll('button'), function(b){ b.setAttribute('disabled','disabled'); });\n      playSound('click');\n      submitAnswer({ placement: participantAnswerLocalState.dragPlacement.slice() });\n    };\n  }\n  paint();\n}\n\n\n// ============================================================\n// Intermission screen: shown to participants briefly after an\n// answer is revealed, before the next question appears. Combines\n// a rotating phrase from a pool (~18 phrases) with a lightweight\n// animated SVG graphic (varied each time, not one fixed mascot -\n// per Roshan's explicit choice). Pure CSS/SVG animation, no image\n// assets, so this stays tiny and self-contained.\n// ============================================================\n\nvar INTERMISSION_PHRASES = [\n  \"Nice work! Here comes the next one...\",\n  \"Keep that momentum going!\",\n  \"Let's see what's next...\",\n  \"You're doing great. Next question incoming!\",\n  \"Can you keep your streak alive?\",\n  \"Sharpen up for the next one!\",\n  \"Halfway there! Stay focused.\",\n  \"Great effort. On to the next challenge!\",\n  \"The next question is loading...\",\n  \"Every answer counts. Keep going!\",\n  \"Nicely done! Let's keep the energy up.\",\n  \"One down, more to go!\",\n  \"You're on a roll!\",\n  \"Stay sharp, here's what's next...\",\n  \"Great pace so far!\",\n  \"Ready for a curveball?\",\n  \"The leaderboard is heating up!\",\n  \"Let's keep this energy going!\"\n];\n\n// Each graphic is a small self-contained inline SVG animation, using only\n// CSS keyframes (no JS animation loop needed) so these are extremely\n// lightweight. Rotated through randomly for visual variety each time.\nvar INTERMISSION_GRAPHICS = [\n  // 1. Bouncing dots\n  '<svg width=\"120\" height=\"120\" viewBox=\"0 0 120 120\"><circle cx=\"30\" cy=\"60\" r=\"10\" fill=\"#0000FF\" class=\"ig-bounce\" style=\"animation-delay:0s\"/><circle cx=\"60\" cy=\"60\" r=\"10\" fill=\"#00A2FF\" class=\"ig-bounce\" style=\"animation-delay:.15s\"/><circle cx=\"90\" cy=\"60\" r=\"10\" fill=\"#09BC09\" class=\"ig-bounce\" style=\"animation-delay:.3s\"/></svg>',\n  // 2. Spinning ring segments\n  '<svg width=\"120\" height=\"120\" viewBox=\"0 0 120 120\" class=\"ig-spin\"><circle cx=\"60\" cy=\"60\" r=\"45\" fill=\"none\" stroke=\"#CFF91C\" stroke-width=\"10\" stroke-dasharray=\"60 200\" stroke-linecap=\"round\"/><circle cx=\"60\" cy=\"60\" r=\"45\" fill=\"none\" stroke=\"#0000FF\" stroke-width=\"10\" stroke-dasharray=\"30 230\" stroke-dashoffset=\"-150\" stroke-linecap=\"round\"/></svg>',\n  // 3. Pulsing rings\n  '<svg width=\"120\" height=\"120\" viewBox=\"0 0 120 120\"><circle cx=\"60\" cy=\"60\" r=\"20\" fill=\"none\" stroke=\"#00A2FF\" stroke-width=\"4\" class=\"ig-pulse\" style=\"animation-delay:0s\"/><circle cx=\"60\" cy=\"60\" r=\"20\" fill=\"none\" stroke=\"#09BC09\" stroke-width=\"4\" class=\"ig-pulse\" style=\"animation-delay:.4s\"/><circle cx=\"60\" cy=\"60\" r=\"20\" fill=\"none\" stroke=\"#0000FF\" stroke-width=\"4\" class=\"ig-pulse\" style=\"animation-delay:.8s\"/></svg>',\n  // 4. Rotating triangle/star burst\n  '<svg width=\"120\" height=\"120\" viewBox=\"0 0 120 120\" class=\"ig-spin-slow\"><polygon points=\"60,20 70,50 100,50 76,68 86,98 60,80 34,98 44,68 20,50 50,50\" fill=\"#FEDA00\"/></svg>',\n  // 5. Sliding bars\n  '<svg width=\"120\" height=\"120\" viewBox=\"0 0 120 120\"><rect x=\"20\" y=\"45\" width=\"20\" height=\"30\" rx=\"6\" fill=\"#0000FF\" class=\"ig-slide\" style=\"animation-delay:0s\"/><rect x=\"50\" y=\"45\" width=\"20\" height=\"30\" rx=\"6\" fill=\"#00A2FF\" class=\"ig-slide\" style=\"animation-delay:.1s\"/><rect x=\"80\" y=\"45\" width=\"20\" height=\"30\" rx=\"6\" fill=\"#09BC09\" class=\"ig-slide\" style=\"animation-delay:.2s\"/></svg>'\n];\n\nvar INTERMISSION_CSS =\n'.intermission-overlay{position:fixed;inset:0;z-index:20;display:flex;align-items:center;justify-content:center;background:rgba(246,247,251,.88);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px)}' +\n'.intermission-card{background:rgba(255,255,255,.92);border-radius:28px;padding:40px 36px;text-align:center;box-shadow:0 16px 40px rgba(14,21,64,.18);max-width:340px;animation:im-pop .4s ease-out}' +\n'.intermission-phrase{font-size:19px;font-weight:900;color:var(--navy);margin-top:16px}' +\n'@keyframes im-pop{0%{transform:scale(.85);opacity:0}100%{transform:scale(1);opacity:1}}' +\n'.ig-bounce{animation:ig-bounce-kf 0.9s infinite ease-in-out}' +\n'@keyframes ig-bounce-kf{0%,100%{transform:translateY(0)}50%{transform:translateY(-18px)}}' +\n'.ig-spin{animation:ig-spin-kf 1.6s linear infinite;transform-origin:60px 60px}' +\n'.ig-spin-slow{animation:ig-spin-kf 3s linear infinite;transform-origin:60px 60px}' +\n'@keyframes ig-spin-kf{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}' +\n'.ig-pulse{animation:ig-pulse-kf 1.6s infinite ease-out;transform-origin:60px 60px}' +\n'@keyframes ig-pulse-kf{0%{transform:scale(.6);opacity:1}100%{transform:scale(1.6);opacity:0}}' +\n'.ig-slide{animation:ig-slide-kf 0.8s infinite ease-in-out}' +\n'@keyframes ig-slide-kf{0%,100%{transform:scaleY(1)}50%{transform:scaleY(1.6) translateY(-10px)}}';\n\nvar intermissionState = { activeForQuestionKey: null, timeoutId: null };\n\nfunction showIntermission(questionKeyJustRevealed){\n  if (intermissionState.activeForQuestionKey === questionKeyJustRevealed) return; // already shown for this reveal\n  intermissionState.activeForQuestionKey = questionKeyJustRevealed;\n\n  var overlay = document.getElementById('intermissionOverlay');\n  if (!overlay) return;\n  var phrase = INTERMISSION_PHRASES[Math.floor(Math.random()*INTERMISSION_PHRASES.length)];\n  var graphic = INTERMISSION_GRAPHICS[Math.floor(Math.random()*INTERMISSION_GRAPHICS.length)];\n  overlay.innerHTML = '<div class=\"intermission-card\">' + graphic +\n    '<div class=\"intermission-phrase\">' + phrase + '</div></div>';\n  overlay.classList.remove('hide');\n  playSound('whoosh');\n\n  clearTimeout(intermissionState.timeoutId);\n  intermissionState.timeoutId = setTimeout(function(){\n    overlay.classList.add('hide');\n  }, 3200);\n}\n\nfunction hideIntermission(){\n  var overlay = document.getElementById('intermissionOverlay');\n  if (overlay) overlay.classList.add('hide');\n  clearTimeout(intermissionState.timeoutId);\n}\n\n\n// ============================================================\n// Full-screen finale: shown when the admin triggers 'finale' on\n// the last question. Podium treatment for 1st/2nd/3rd with\n// creative congratulatory messages, full leaderboard below,\n// confetti, and a fanfare sound.\n// ============================================================\n\nvar FINALE_MESSAGES_FIRST = [\n  \"Absolute standout performance \\u2014 you read every moment perfectly.\",\n  \"First place, fully earned. That's the kind of instinct we love to see.\",\n  \"You didn't just win \\u2014 you set the pace for everyone else.\",\n  \"Top of the leaderboard and clearly no accident. Well played.\",\n  \"Sharp, fast, and accurate \\u2014 a genuinely impressive run.\"\n];\nvar FINALE_MESSAGES_SECOND = [\n  \"So close to the top \\u2014 a genuinely strong showing.\",\n  \"Second place with a performance that kept everyone on their toes.\",\n  \"Just a step behind the leader, but way ahead of the pack.\",\n  \"A great run \\u2014 the gap at the top is closer than it looks.\"\n];\nvar FINALE_MESSAGES_THIRD = [\n  \"Rounding out the podium with a solid, consistent performance.\",\n  \"Third place and firmly in the conversation for the win.\",\n  \"A strong finish \\u2014 right there with the leaders the whole way.\"\n];\nvar FINALE_MESSAGES_PARTICIPANT = [\n  \"Great effort today \\u2014 every question sharpened your instincts.\",\n  \"Thanks for playing full-out \\u2014 see you at the next session.\",\n  \"Solid participation \\u2014 the real win is the practice you got in.\"\n];\n\nfunction pick(arr){ return arr[Math.floor(Math.random()*arr.length)]; }\n\nfunction renderFinaleContent(state, myPid){\n  var host = document.getElementById('finaleScreen');\n  var arr = Object.values(state.participants).sort(function(a,b){ return (b.score||0)-(a.score||0); });\n\n  var podiumHtml = '';\n  var podiumOrder = [1,0,2]; // visually: 2nd, 1st, 3rd (classic podium arrangement)\n  var heights = { 0:'190px', 1:'150px', 2:'120px' };\n  var labels = { 0:'1st', 1:'2nd', 2:'3rd' };\n\n  podiumOrder.forEach(function(rank){\n    var p = arr[rank];\n    if (!p) return;\n    var msg = rank===0 ? pick(FINALE_MESSAGES_FIRST) : (rank===1 ? pick(FINALE_MESSAGES_SECOND) : pick(FINALE_MESSAGES_THIRD));\n    podiumHtml += '<div class=\"podium-col\">' +\n      '<div class=\"podium-avatar\">' + avatarImg(p.avatar||'robot') + '</div>' +\n      '<div class=\"podium-name\">' + escapeHtml(p.name) + '</div>' +\n      '<div class=\"podium-score\">' + (p.score||0) + ' pts</div>' +\n      '<div class=\"podium-block podium-rank-'+rank+'\" style=\"height:'+heights[rank]+'\"><span>'+labels[rank]+'</span></div>' +\n      '<div class=\"podium-msg\">' + msg + '</div>' +\n      '</div>';\n  });\n\n  var me = state.participants[myPid];\n  var myRank = arr.findIndex(function(p){ return p.id === myPid; });\n  var myMessageHtml = '';\n  if (me && myRank > 2){\n    myMessageHtml = '<div class=\"finale-personal\">' +\n      '<div class=\"avmini\" style=\"width:44px;height:44px;display:inline-flex;vertical-align:middle;margin-right:10px\">' + avatarImg(me.avatar||'robot') + '</div>' +\n      '<span>You finished #' + (myRank+1) + ' with ' + (me.score||0) + ' points. ' + pick(FINALE_MESSAGES_PARTICIPANT) + '</span>' +\n      '</div>';\n  }\n\n  var restHtml = arr.slice(3).map(function(p, i){\n    return '<li class=\"lrow\"><span class=\"lrank\">' + (i+4) + '</span>' +\n      '<span class=\"avmini\">' + avatarImg(p.avatar||'robot') + '</span>' +\n      '<span class=\"lname\">' + escapeHtml(p.name) + '</span>' +\n      '<span><div class=\"lscore\">' + (p.score||0) + '</div></span></li>';\n  }).join('');\n\n  host.innerHTML =\n    '<div class=\"finale-inner\">' +\n      '<div class=\"gtitle finale-title\">Final Results</div>' +\n      '<div class=\"podium-wrap\">' + podiumHtml + '</div>' +\n      myMessageHtml +\n      (restHtml ? '<div class=\"gcard\" style=\"margin-top:24px;max-width:520px;margin-left:auto;margin-right:auto\"><h2 style=\"font-size:16px\">Full Leaderboard</h2><ol class=\"leader\" style=\"list-style:none;padding:0\">' + restHtml + '</ol></div>' : '') +\n    '</div>';\n\n  host.classList.remove('hide');\n  launchFinaleConfetti();\n  playSound('fanfare');\n}\n\nfunction launchFinaleConfetti(){\n  var colors = ['#0000FF','#00A2FF','#FEDA00','#09BC09','#CFF91C'];\n  for (var burst = 0; burst < 3; burst++){\n    setTimeout(function(){\n      for (var i = 0; i < 40; i++){\n        var el = document.createElement('div');\n        el.className = 'confetti-piece';\n        var size = 6 + Math.random()*8;\n        el.style.width = size + 'px';\n        el.style.height = (size*0.5) + 'px';\n        el.style.left = (Math.random()*100) + 'vw';\n        el.style.background = colors[Math.floor(Math.random()*colors.length)];\n        var duration = 2.5 + Math.random()*1.8;\n        el.style.animation = 'confettiFall ' + duration + 's ease-in forwards';\n        el.style.transform = 'rotate(' + Math.floor(Math.random()*360) + 'deg)';\n        document.body.appendChild(el);\n        (function(node, dur){ setTimeout(function(){ node.remove(); }, dur*1000+100); })(el, duration);\n      }\n    }, burst * 500);\n  }\n}\n\nvar FINALE_CSS =\n'#finaleScreen{position:fixed;inset:0;z-index:15;overflow-y:auto;background:linear-gradient(180deg,rgba(246,247,251,.97),rgba(255,255,255,.99))}' +\n'.finale-inner{max-width:720px;margin:0 auto;padding:50px 20px 60px;text-align:center}' +\n'.finale-title{font-size:34px!important;margin-bottom:30px}' +\n'.podium-wrap{display:flex;align-items:flex-end;justify-content:center;gap:16px;margin-bottom:20px;flex-wrap:wrap}' +\n'.podium-col{display:flex;flex-direction:column;align-items:center;width:150px}' +\n'.podium-avatar{width:60px;height:60px;border-radius:50%;background:rgba(255,255,255,.9);display:flex;align-items:center;justify-content:center;box-shadow:0 6px 14px rgba(14,21,64,.15);margin-bottom:8px}' +\n'.podium-avatar img{width:70%;height:70%;object-fit:contain}' +\n'.podium-name{font-weight:900;color:var(--navy);font-size:14px}' +\n'.podium-score{font-weight:800;color:var(--grey);font-size:12px;margin-bottom:8px}' +\n'.podium-block{width:100%;border-radius:14px 14px 0 0;display:flex;align-items:flex-start;justify-content:center;padding-top:10px;font-weight:900;color:#fff;font-size:18px;box-shadow:0 -4px 14px rgba(14,21,64,.12)}' +\n'.podium-rank-0{background:linear-gradient(180deg,#FEDA00,#FFB800)}' +\n'.podium-rank-1{background:linear-gradient(180deg,#00A2FF,#0072FF)}' +\n'.podium-rank-2{background:linear-gradient(180deg,#09BC09,#068906)}' +\n'.podium-msg{font-size:11.5px;color:var(--ink);margin-top:10px;line-height:1.4;padding:0 4px}' +\n'.finale-personal{background:rgba(255,255,255,.85);border-radius:16px;padding:14px 18px;margin:20px auto 0;max-width:460px;font-size:13px;font-weight:600;color:var(--navy);box-shadow:0 6px 16px rgba(14,21,64,.08)}';\n\n\n(function(){\n\"use strict\";\nvar AVATAR_IDS = ['astronaut','robot','ninja','alien','wizard','fox','panda','dragon','cat','owl','unicorn','ghost'];\nvar params = new URLSearchParams(location.search);\nvar codeFromUrl = (params.get('code') || '').toUpperCase();\nif (codeFromUrl) document.getElementById('codein').value = codeFromUrl;\n\nvar pid;\ntry { pid = sessionStorage.getItem('pid') || (crypto.randomUUID ? crypto.randomUUID() : String(Math.random())); sessionStorage.setItem('pid', pid); }\ncatch(e){ pid = 'p_' + Math.random().toString(36).slice(2); }\n\nvar selectedAvatar = 'robot';\ntry {\n  var savedAvatar = sessionStorage.getItem('avatar');\n  if (savedAvatar && AVATAR_IDS.indexOf(savedAvatar) !== -1) selectedAvatar = savedAvatar;\n} catch(e){}\n\nfunction avatarImg(id, cls){\n  var src = (typeof AVATAR_DATA !== 'undefined' && AVATAR_DATA[id]) ? AVATAR_DATA[id] : '';\n  return '<img src=\"' + src + '\" alt=\"' + id + '\" class=\"' + (cls||'') + '\">';\n}\n\nfunction buildAvatarGrid(){\n  var grid = document.getElementById('avgrid');\n  if (!grid) return;\n  grid.innerHTML = AVATAR_IDS.map(function(id){\n    return '<div class=\"avitem' + (id === selectedAvatar ? ' selected' : '') + '\" data-avatar=\"' + id + '\">' +\n      '<div class=\"avorb\">' + avatarImg(id) + '</div>' +\n      '<div class=\"avlabel\">' + id + '</div></div>';\n  }).join('');\n  Array.prototype.forEach.call(grid.querySelectorAll('.avitem'), function(el){\n    el.onclick = function(){\n      selectedAvatar = el.getAttribute('data-avatar');\n      try { sessionStorage.setItem('avatar', selectedAvatar); } catch(e){}\n      Array.prototype.forEach.call(grid.querySelectorAll('.avitem'), function(e2){\n        e2.classList.toggle('selected', e2 === el);\n      });\n      playSound('tick');\n    };\n  });\n}\nbuildAvatarGrid();\n\nvar state = { code:'', phase:'lobby', participants:{}, question:null, answers:{}, reveal:false, showBoard:false, finale:false };\nvar ws = null, reconnectDelay = 1000, joined = false, myCode = '';\nvar localQuestionSeenAt = null;\nvar lastRenderedQuestionKey = null, timerInterval;\nvar lastRevealedQuestionKey = null; // tracks which question's reveal we've already played sound/confetti for\n\nfunction setConnPill(ok, label){\n  var p = document.getElementById('connpill');\n  p.textContent = label;\n  p.style.background = ok ? '#ECFFEC' : '#FFECEC';\n  p.style.color = ok ? '#067806' : '#B50000';\n}\n\nfunction connectTo(code){\n  myCode = code;\n  var proto = location.protocol === 'https:' ? 'wss:' : 'ws:';\n  ws = new WebSocket(proto + '//' + location.host + '/ws?code=' + encodeURIComponent(code) + '&role=participant');\n  ws.onopen = function(){\n    reconnectDelay = 1000; setConnPill(true, 'Connected');\n    if (joined) send({ type:'join', id:pid, name:document.getElementById('name').value.trim()||'Guest', avatar:selectedAvatar });\n  };\n  ws.onmessage = function(evt){\n    var msg; try { msg = JSON.parse(evt.data); } catch(e){ return; }\n    if (msg.kind === 'state') { state = msg.state; render(); }\n    else if (msg.kind === 'error') { handleServerError(msg.reason); }\n  };\n  ws.onclose = function(){\n    setConnPill(false, 'Reconnecting');\n    setTimeout(function(){ connectTo(myCode); }, reconnectDelay);\n    reconnectDelay = Math.min(reconnectDelay * 1.6, 8000);\n  };\n  ws.onerror = function(){ try{ ws.close(); }catch(e){} };\n}\n\nfunction send(obj){ if (ws && ws.readyState === 1) ws.send(JSON.stringify(obj)); }\n\nfunction showMsg(id, text){\n  var el = document.getElementById(id);\n  el.textContent = text; el.classList.add('show');\n  setTimeout(function(){ el.classList.remove('show'); }, 3000);\n}\n\nfunction handleServerError(reason){\n  if (reason === 'time_expired'){ showMsg('quizMsg', \"Time is up for this question \\u2014 your answer was not recorded.\"); }\n  else if (reason === 'invalid_option'){ showMsg('quizMsg', 'That could not be recorded. Please try again.'); }\n  else if (reason === 'no_active_question'){ showMsg('quizMsg', 'There is no active question right now.'); }\n}\n\ndocument.getElementById('joinbtn').onclick = function(){\n  unlockAudio();\n  var code = document.getElementById('codein').value.trim().toUpperCase();\n  var nm = document.getElementById('name').value.trim();\n  if (!code){ showMsg('joinMsg', 'Please enter the session code.'); return; }\n  if (!nm){ showMsg('joinMsg', 'Please enter your display name.'); return; }\n  joined = true;\n  document.getElementById('waitCode').textContent = code;\n  document.getElementById('waitAvatar').innerHTML = avatarImg(selectedAvatar);\n  if (ws && ws.readyState === 1 && myCode === code) { send({ type:'join', id:pid, name:nm, avatar:selectedAvatar }); }\n  else { connectTo(code); }\n  document.getElementById('join').classList.add('hide');\n  document.getElementById('waiting').classList.remove('hide');\n};\n\n// This function is called by every renderXAnswer() function in\n// participant_answer_types.js once the participant has made their choice.\n// IMPORTANT: participant_answer_types.js is intentionally NOT wrapped in\n// its own IIFE, so any function it calls (like submitAnswer) must be\n// reachable from the GLOBAL scope, not just from inside this closure.\n// Exposing it on window is what makes that cross-file call actually work\n// (verified this was broken without this line - see test_scope_bug.js).\nwindow.submitAnswer = function(payload){\n  payload.id = pid;\n  payload.type = 'answer';\n  send(payload);\n};\n\nfunction render(){\n  if (state.finale){ renderFinale(); return; }\n  document.getElementById('finaleScreen').classList.add('hide');\n\n  var me = state.participants[pid];\n  var showJoinScreen = !joined || !me;\n  document.getElementById('join').classList.toggle('hide', joined);\n  document.getElementById('waiting').classList.toggle('hide', showJoinScreen || state.phase === 'live');\n\n  var alreadyAnswered = !!(state.answers && state.answers[pid]);\n  var inLiveQuestion = !!(me && state.phase === 'live' && state.question);\n\n  if (inLiveQuestion){\n    var qKey = state.question.started;\n    if (qKey !== lastRenderedQuestionKey){\n      localQuestionSeenAt = Date.now();\n      lastRenderedQuestionKey = qKey;\n      document.getElementById('answerArea').innerHTML = '';\n      renderAnswerUI(state.question, false, null);\n      hideIntermission();\n    }\n  }\n\n  var timeIsUp = !!(inLiveQuestion && localQuestionSeenAt !== null &&\n    Date.now() > localQuestionSeenAt + state.question.duration*1000);\n  var missedIt = inLiveQuestion && !alreadyAnswered && timeIsUp && !state.reveal;\n\n  document.getElementById('quiz').classList.toggle('hide', showJoinScreen || !inLiveQuestion || alreadyAnswered || missedIt);\n  document.getElementById('missed').classList.toggle('hide', showJoinScreen || !missedIt);\n  document.getElementById('submitted').classList.toggle('hide', showJoinScreen || !inLiveQuestion || !alreadyAnswered || state.reveal);\n  document.getElementById('result').classList.toggle('hide', showJoinScreen || !inLiveQuestion || !alreadyAnswered || !state.reveal);\n  document.getElementById('lb').classList.toggle('hide', showJoinScreen || !state.showBoard);\n\n  if (!showJoinScreen && inLiveQuestion){\n    document.getElementById('qview').textContent = state.question.text;\n    if (!alreadyAnswered && !missedIt) startTimer();\n    var a = state.answers && state.answers[pid];\n    if (a && state.reveal){\n      if (lastRevealedQuestionKey !== qKey){\n        lastRevealedQuestionKey = qKey;\n        showResult(a, state.question);\n        showIntermission(qKey);\n      }\n    }\n    if (a && !state.reveal){ document.getElementById('submittedChoice').textContent = 'Your response has been recorded.'; }\n  }\n  renderLeader();\n}\n\nfunction startTimer(){\n  clearInterval(timerInterval);\n  if (!state.question || localQuestionSeenAt === null) return;\n  var d = state.question.duration, end = localQuestionSeenAt + d*1000;\n  var circumference = 2 * Math.PI * 52;\n  var ringEl = document.getElementById('ringProgress');\n  var numEl = document.getElementById('ringNum');\n  var lastWholeSec = null;\n  timerInterval = setInterval(function(){\n    var left = Math.max(0, end - Date.now());\n    var pct = left / (d*1000);\n    var secs = Math.ceil(left/1000);\n    if (ringEl){\n      var dash = circumference * pct;\n      ringEl.setAttribute('stroke-dasharray', dash.toFixed(1) + ' ' + (circumference-dash).toFixed(1));\n    }\n    if (numEl) numEl.textContent = secs;\n    if (secs <= 5 && secs !== lastWholeSec && secs > 0){ playSound('countdown_tick'); }\n    lastWholeSec = secs;\n    if (!left){ clearInterval(timerInterval); render(); }\n  }, 100);\n}\n\nfunction showResult(a, question){\n  var body = document.getElementById('resultBody');\n  var graded = ['mc','tf','multi','image','ranking','matching','dragdrop'].indexOf(question.type) !== -1;\n  if (!graded){\n    body.innerHTML = '<h2>Thanks for your response!</h2><p class=\"muted\">This question was for feedback and is not scored.</p>';\n    playSound('whoosh');\n    return;\n  }\n  if (a.correct){\n    body.innerHTML = '<h2 style=\"color:#09BC09\">Correct!</h2><div class=\"basepts\">Base points +' + a.base + '</div>' +\n      '<div class=\"bonus\">+' + a.bonus + '</div><p class=\"muted\">Speed bonus</p>' +\n      '<div class=\"rankline\">Total earned +' + (a.base+a.bonus) + ' \\u00b7 Rank #' + a.rank + '</div>';\n    playSound('correct');\n    launchConfetti();\n  } else {\n    body.innerHTML = '<h2>Not Quite</h2><div class=\"bonus\" style=\"color:#929292\">+0</div>' +\n      '<p class=\"muted\">Better luck on the next question!</p>';\n    playSound('incorrect');\n  }\n}\n\nfunction launchConfetti(){\n  var colors = ['#0000FF','#00A2FF','#FEDA00','#09BC09','#CFF91C'];\n  for (var i = 0; i < 28; i++){\n    var el = document.createElement('div');\n    el.className = 'confetti-piece';\n    var size = 6 + Math.random()*6;\n    el.style.width = size + 'px';\n    el.style.height = (size*0.5) + 'px';\n    el.style.left = (Math.random()*100) + 'vw';\n    el.style.background = colors[Math.floor(Math.random()*colors.length)];\n    var duration = 2.2 + Math.random()*1.4;\n    el.style.animation = 'confettiFall ' + duration + 's ease-in forwards';\n    el.style.transform = 'rotate(' + Math.floor(Math.random()*360) + 'deg)';\n    document.body.appendChild(el);\n    (function(node, dur){ setTimeout(function(){ node.remove(); }, dur*1000 + 100); })(el, duration);\n  }\n}\n\nfunction renderLeader(){\n  if (!state.participants) return;\n  var arr = Object.values(state.participants).sort(function(a,b){ return (b.score||0)-(a.score||0); });\n  document.getElementById('leader').innerHTML = arr.map(function(p, i){\n    var rankCls = i===0 ? 'r1' : (i===1 ? 'r2' : (i===2 ? 'r3' : ''));\n    var rowCls = i===0 ? 'top1' : '';\n    var fastestBadge = (i===0 && p.lastDelta) ? '<div class=\"lfastest\">Top scorer</div>' : '';\n    return '<li class=\"lrow ' + rowCls + '\">' +\n      '<span class=\"lrank ' + rankCls + '\">' + (i+1) + '</span>' +\n      '<span class=\"avmini\">' + avatarImg(p.avatar||'robot') + '</span>' +\n      '<span><span class=\"lname\">' + p.name + '</span>' + fastestBadge + '</span>' +\n      '<span><div class=\"lscore\">' + (p.score||0) + '</div>' +\n      (p.lastDelta ? '<div class=\"ldelta\">+' + p.lastDelta + '</div>' : '') + '</span></li>';\n  }).join('');\n}\n\n// renderFinaleContent is defined in finale.js (loaded alongside this file).\n// It is a plain global function (finale.js is intentionally not wrapped in\n// its own IIFE, same pattern as participant_answer_types.js), so it is\n// safely callable from inside this closure.\nvar finaleShownForSession = false;\nfunction renderFinale(){\n  if (!finaleShownForSession){\n    finaleShownForSession = true;\n    renderFinaleContent(state, pid);\n  }\n}\n\nif (codeFromUrl){ connectTo(codeFromUrl); } else { setConnPill(false, 'Enter a code to connect'); }\nrender();\n\nwindow.__participantExports = { render: render, submitAnswer: submitAnswer, avatarImg: avatarImg };\n})();\n" + '</' + 'script>' + "\n</body></html>\n";
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (url.pathname === '/health') {
      return Response.json({ status: 'ok', application: 'CLE Live Quiz', realtime: 'active', version: 'v4-full' });
    }

    if (url.pathname === '/ws') {
      const code = (url.searchParams.get('code') || 'LEARN6').toUpperCase();
      const id = env.SESSION_ROOM.idFromName(code);
      const stub = env.SESSION_ROOM.get(id);
      return stub.fetch(request);
    }

    if (url.pathname === '/api/bank') {
      const id = env.QUESTION_BANK.idFromName('global');
      const stub = env.QUESTION_BANK.get(id);
      return stub.fetch(request);
    }

    if (url.pathname === '/admin') {
      return new Response(adminHtml(), {
        headers: { 'Content-Type': 'text/html; charset=UTF-8', 'Cache-Control': 'no-store' }
      });
    }

    if (url.pathname === '/join' || url.pathname === '/') {
      return new Response(participantHtml(), {
        headers: { 'Content-Type': 'text/html; charset=UTF-8', 'Cache-Control': 'no-store' }
      });
    }

    return new Response('Not found', { status: 404 });
  }
};
